// مولّدة آلياً بواسطة scripts/split-fatwas.mjs — لا تُعدَّل يدوياً.
export default [{"id":12,"question":"لقد تزوج والدي زوجةَ ولد أخيه بعد وفاته بسنوات، وأنجب منها ولدًا وطفلتين، وأريد أنا الزواج من ابنتها التي من زوجها السابق، فهل يجوز ذلك أم لا؟","title":"حكم الزواج بربيبة الأب أو أم زوجته","answer":"الجواب: نعم، ما فيه شيء، إذا تزوج أبوك زوجةَ ولد أخيه، أو تزوَّج زوجة أخيه بعد طلاقه لها، أو موته، أو زوجة عمّه أو خاله؛ فلا بأس، ولك أن تنكح بنت الزوجة من غير أبيك، سواء كانت هذه البنتُ من زوجٍ قبله أو زوجٍ بعده، فهي أجنبية منك، إنما هي ربيبةٌ لأبيك، لا ينكحها أبوك، وأما أنت فهي أجنبيةٌ، فإذا تزوج الإنسانُ امرأةً وتزوَّج ابنُه بنتَها أو أمَّها فلا بأس.","link":"https://binbaz.org.sa/fatwas/2791/حكم-الزواج-بربيبة-الاب-او-ام-زوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0264.mp3","categories":["شروط وأركان الزواج","أحكام المولود"]},{"id":109,"question":"يقول السائل: إذا عُقد قران على زوجةٍ، وكانت الزوجة والزوج مُقصرين في أداء الصلاة، أي: يُصليان أوقاتًا ويتركان أوقاتًا، فما صحَّة ذلك العقد؟ وهل الأطفال حلالٌ أم حرامٌ إن وُجِدُوا؟","title":"أثر عدم الصلاة على صحة العقد بين الزوجين","answer":"الجواب: إذا كان الزوجان يُصليان أو لا يُصليان فالعقد صحيح، والأولاد يُلحقون بهم؛ لشُبهة النكاح، إذا كانا يُصليان أو لا يُصليان جميعًا، فالنكاح صحيحٌ كسائر الكفرة، نكاحهم صحيحٌ على حسب ما اعتادوه في أنكحتهم.\nأما إذا كان واحدٌ يُصلي وواحدٌ ما يُصلي فلا يصح النكاح، ولا بدّ أن يُجدد إذا كانت هي تُصلي وهو ما يُصلي، أو هو يُصلي وهي ما تُصلي؛ لأنَّ ترك الصلاة كفرٌ مطلقًا على الأصح، وإن كانت ما جحدت وجوبها، وإن كان ما جحد وجوبها، يقول النبيُّ ﷺ: بين الرجل وبين الكفر والشِّرك: ترك الصلاة، ويقول ﷺ: العهد الذي بيننا وبينهم الصلاة، فمَن تركها فقد كفر.\nفإذا كانت لا تُصلي وجب تجديد النكاح، أو كان هو لا يُصلي أو يُصلي تارةً ويترك تارةً أو هي كذلك وجب التَّجديد، فيُعاد النكاح بعد توبتهما، إذا تاب مَن ترك الصلاة، فإذا تاب تاركُ الصلاة إلى الله يُجدد النكاح بعقدٍ جديدٍ، وشهادة عدلين، ومهر جديد ولو قليلًا، ولو لم يذهبوا إلى المحكمة، ولو لم يذهبوا إلى المسؤول، ولكن هم بأنفسهم يفعلون ذلك، يعني: يحضر الولي والزوج وشاهدان عدلان، ويُجدد النكاح بشرط المهر الذي ترضى به المرأة ولو قليلًا، يقول: زوَّجْتُك، ويقول: قبلتُ على مهر كذا، بحضرة شاهدين، إذا كان أحدُهما حين العقد الأول لا يُصلي.\nأما إذا كانا يُصليان فهذا معروفٌ، أو كانا لا يُصليان جميعًا فعقدهما صحيحٌ؛ لأنَّهما اشتركا في الكفر: كالوثنين، واليهود، والنصارى، وأشباههم، فأنكحتهم صحيحة على ما اعتادوه في دينهم، وإنما المُصيبة إذا كان أحدُهما لا يُصلي، هذا هو محل تجديد النكاح -نسأل الله للجميع الهداية.","link":"https://binbaz.org.sa/fatwas/3545/اثر-عدم-الصلاة-على-صحة-العقد-بين-الزوجين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0092.mp3","categories":["شروط وأركان الزواج","أحكام المولود"]},{"id":499,"question":"هل يعق عن الولد إذا خرج ميتًا من بطن أمه؟","title":"هل يُعَقّ عن المولود إذا خرج ميتًا؟","answer":"الجواب: نعم يُعَقّ عنه.\n(دروس شرح بلوغ المرام، كتاب الاطعمة)","link":"https://binbaz.org.sa/fatwas/6277/هل-يعق-عن-المولود-اذا-خرج-ميتا","audio":"https://files.zadapps.info/binbaz.org.sa/maram063 - 02 - .mp3","categories":["أحكام المولود"]},{"id":500,"question":"تأخير الحلاقة للمولود؟","title":"متى وقت حلاقة المولود؟","answer":"الجواب: ج: الأفضل في اليوم السابع، وإن أخّرها فلا حرج.\n(دروس شرح بلوغ المرام، كتاب الأطعمة)","link":"https://binbaz.org.sa/fatwas/6278/متى-وقت-حلاقة-المولود","audio":"https://files.zadapps.info/binbaz.org.sa/maram064 - 02 - .mp3","categories":["أحكام المولود"]},{"id":501,"question":"من بلغ الرشد ولم يُعَقّ عنه؟","title":"ما حكم العقيقة عن البالغ؟","answer":"الجواب: العقيقة في حق أبيه، وإن عق عن نفسه فلا بأس.\n(دروس شرح بلوغ المرام، كتاب الأطعمة)","link":"https://binbaz.org.sa/fatwas/6280/ما-حكم-العقيقة-عن-البالغ","audio":"https://files.zadapps.info/binbaz.org.sa/maram065  - 02 - .mp3","categories":["أحكام المولود"]},{"id":503,"question":"تسميتها للعقيقة والعقيقة من العقوق؟","title":"ما الأصل في تسمية العقيقة؟","answer":"الجواب: يعني اشتهرت بهذا الاسم، ولا بأس، مثل ما قالت عائشة: أمر الرسول ﷺ أن يُعَق عن الغلام شاتان.\n(دروس شرح بلوغ المرام، كتاب الأطعمة)","link":"https://binbaz.org.sa/fatwas/6282/ما-الاصل-في-تسمية-العقيقة","audio":"https://files.zadapps.info/binbaz.org.sa/maram067 - 02 - .mp3","categories":["أحكام المولود"]},{"id":504,"question":"هل شروط الأضحية والعقيقة والهَدْي سواء؟","title":"هل شروط الأضحية والعقيقة والهَدْي سواء؟","answer":"الجواب: نعم، سواء، لا يجزي فيها إلا في الأضاحي، لا في الهدي ولا في العقيقة، لا يجزي فيها إلا ما يجزي في الأضاحي.\n(دروس شرح بلوغ المرام، كتاب الأطعمة)","link":"https://binbaz.org.sa/fatwas/6283/هل-شروط-الاضحية-والعقيقة-والهدي-سواء","audio":"undefined","categories":["الهدي والأضاحي","أحكام المولود"]},{"id":505,"question":"التحنيك يوم الولادة أم في اليوم السابع؟","title":"متى يكون وقت تحنيك المولود؟","answer":"الجواب: يوم الولادة أفضل.\n(دروس شرح بلوغ المرام، كتاب الأطعمة)","link":"https://binbaz.org.sa/fatwas/6284/متى-يكون-وقت-تحنيك-المولود","audio":"https://files.zadapps.info/binbaz.org.sa/maram069  - 02 - .mp3","categories":["أحكام المولود"]},{"id":506,"question":"السقط له عقيقة؟","title":"ما حكم العقيقة عن السَّقْط؟","answer":"الجواب: إذا كان في الخامس وما بعده، ونفخت في الروح؛ تعمه الأحاديث ويُسمّى.\n(دروس شرح بلوغ المرام، كتاب الأطعمة)","link":"https://binbaz.org.sa/fatwas/6285/ما-حكم-العقيقة-عن-السقط","audio":"https://files.zadapps.info/binbaz.org.sa/maram070 - 02 - .mp3","categories":["أحكام المولود"]},{"id":1155,"question":"ما حكم التَّسمِّي بـ: عبدالرشيد، وعبدالموجود، وعبدالباقي، وسائر الأسماء التي فيها تعبيد لصفةٍ من صفات الله لم يثبت له اسمٌ؟","title":"حكم أسماء عبدالرشيد، عبدالموجود، عبدالباقي","answer":"الجواب:\nالقاعدة: أنه لا يجوز التَّعبيد لغير الله، لا بد أن يكون المعبَّد له اسمٌ معروفٌ من أسماء الله، فلا يُقال: عبدالموجود، ولا: عبدالقديم؛ لأنَّ هذا ما ثبت من أسماء الله ، ولا عبدالرشيد، إلا بدليلٍ، الرشيد: لا أتذكر الآن شيئًا من النصوص في الرشيد، وإذا ثبت من أسمائه الرشيد جاز، والباقي مشهورٌ: عبدالباقي، من حيث المعنى هو الباقي جلَّ وعلا، لكن لا أعلم نصًّا فيه ذكر اسم الباقي، ولكن معناه صحيح، فإنه جلَّ وعلا هو الآخر، هو الأول والآخر، والباقي بمعنى الآخر، فالأمر فيها سهلٌ، في مسألة عبدالباقي.","link":"https://binbaz.org.sa/fatwas/21208/حكم-اسماء-عبدالرشيد-عبدالموجود-عبدالباقي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1004ما حكم التسمي بعد الرشيد وعبد الموجود وعبد الباقي؟.mp3","categories":["أحكام المولود","الأسماء والصفات"]},{"id":1195,"question":"بعض الناس يُرسل الأضحية أو العقيقة إلى بعض البلاد عن طريق أشخاصٍ أو المصارف، مُخالفين السنة النبوية، ما تعليق سماحتكم على ذلك؟","title":"حكم إرسال الأضحية أو العقيقة خارج بلدها","answer":"الجواب:\nالأفضل أن يذبح العقيقة في بيته، العقيقة يعني: نسيكة الولد، وهي شاتان عن الذكر، وشاة واحدة عن الأنثى، تُسمَّى: عقيقة، وتُسمَّى: تميمة، يُسميها بعض الناس: تميمة، وتُسمَّى: نسيكة، وهي سنة مؤكدة، والرسول ﷺ أمر أن يعقَّ عن الغلام شاتان، وعن الجارية شاة، وتُذبح يوم السابع. هذا هو الأفضل، يذبحها المسلمُ في بيته يوم السابع، ويأكل منها، ويُطعم مَن شاء من جيرانٍ وأقارب وغيرهم، أو يُوزِّعها، يتصدَّق ويُوزِّعها، ولا يُوزِّعها للخارج، الأفضل في بيته، يأكل منها، ويُطعم منها. ولو أرسلها إلى الخارج -إلى المجاهدين أو غير المجاهدين- بيد وكيلٍ ثقةٍ يذبحها هناك ويُوزِّعها؛ فلا بأس، ولكن كونه يذبحها في بيته وبين أهله، ويُحْيُون السُّنة، ويُظهرون السُّنة بينهم وبين جيرانهم، ويأكلون ويُطعمون؛ هذا هو الأفضل، وهو السُّنة.","link":"https://binbaz.org.sa/fatwas/21237/حكم-ارسال-الاضحية-او-العقيقة-خارج-بلدها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1157بعض الناس يرسل أضحيته أو العقيقةخارج البلاد فما الحكم؟ ابن باز فتاوى.mp3","categories":["الهدي والأضاحي","أحكام المولود"]},{"id":1332,"question":"العقيقة عن الولد لها توقيت؟","title":"متى وقت العقيقة وكيفية توزيعها؟","answer":"الجواب:\nالأفضل في اليوم السابع، وإذا ذبح بعد ذلك فلا بأس، لكن الأفضل مثلما قال ﷺ: تذبح عنه يوم سابعه العقيقة، هذا هو الأفضل، تقول عائشة رضي الله عنها: إن فاتت ففي أربعة عشر، فإن فاتت ففي إحدى وعشرين. ثم لا توقيت لها، ولكن بكل حال بعد السابع لا توقيت لها.\nس: مثلًا يحط ذبيحة عن الحريم ثم ذبيحة عن الرجال؟\nج: يوزعها كما يشاء، يتصدق بها كلها، أو يأكل منها ويطعم منها، أو واحدة للرجال وواحدة للنساء، أو واحدة للجيران يوزعها، وواحدة يأكلونها، الأمر في هذا واسع، النبي ما حدّد فيها حدًّا عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/21423/متى-وقت-العقيقة-وكيفية-توزيعها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/متى وقت العقيقة وكيفيتها.mp3","categories":["أحكام المولود"]},{"id":1577,"question":"هذا سؤال ورد إلينا من بعض المصلين: هل من غيَّر اسمَه يُسَنُّ له أن يذبح شاتين عقيقةً، وإن كان قد عُقَّ عنه في أول ولادته؟","title":"هل تجب العقيقة على من غَيَّر اسمه؟","answer":"الجواب:\nلا، ما في حاجة، إذا غيَّر اسمه ما يحتاج عقيقةً، العقيقة مرة واحدة، إذا كان عُقَّ عنه كفى والحمد لله، فإذا غيَّر اسمه باسمٍ أحسن فليس عليه شيء، لا عقيقة، ولا غيرها.","link":"https://binbaz.org.sa/fatwas/21680/هل-تجب-العقيقة-على-من-غير-اسمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تجب العقيقة على من غير اسمه.mp3","categories":["أحكام المولود"]},{"id":1688,"question":"رجل عقَّ عن أولاده بعيرًا، وهم أربع بنات، وولد ذكر، فهل يُعيد مع المشقَّة عليه أو يكفي؟","title":"هل تجزئ البَدَنَة عقيقة عن الأولاد؟","answer":"الجواب:\nنرجو أن يكفي إن شاء الله؛ لأنَّ البَدَنَة تُجزئ عن سبعةٍ، لكن السُّنة أن يعقَّ بالغنم كما بيَّن النبيُّ ﷺ، لكن إذا عقَّ بالبقر، أو الإبل؛ نرجو أن يُجزئه؛ لأنَّ الصحابة ذبحوا البدنةَ عن سبعةٍ، والبقرةَ عن سبعةٍ  في الهدايا، وفي الضَّحايا.\nس: يعني: تقاس العقيقة أو يُقاس..؟\nج: الحكم واحد إلا أنَّ الأفضل الغنم؛ لأنَّ الرسول ﷺ أمر بالغنم، مثلما ضحَّى بكبشين، ومع هذا تُجزئ البَدَنَة.","link":"https://binbaz.org.sa/fatwas/21794/هل-تجزى-البدنة-عقيقة-عن-الاولاد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تجزئ البدنة عقيقة عن الأولاد.mp3","categories":["أحكام المولود"]},{"id":1692,"question":"قد يُرْزَق الرجلُ أربعةَ أولادٍ فهل يعقُّ بشاةٍ واحدةٍ أم لا بد أن يُعَدِّد؟","title":"هل تجزئ شاةٌ واحدة عقيقةً عن أربعة أولاد؟","answer":"الجواب:\nالسُّنة شاتان عن كلِّ واحدٍ، لكن لو عجز وعقَّ بواحدةٍ فالباقي يلحق إن شاء الله، يعقّ بواحدةٍ إذا استطاعها، ثم الثانية إن استطاعها، وإلا ما هو لازم فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16].","link":"https://binbaz.org.sa/fatwas/21798/هل-تجزى-شاة-واحدة-عقيقة-عن-اربعة-اولاد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تجزئ الشاة عقيقة عن أربعة أولاد.mp3","categories":["أحكام المولود"]},{"id":1892,"question":"الجنين إذا نزل من بطن أمه ميتًا هل له عقيقة؟","title":"هل للجنين عقيقة إذا نزل ميتًا؟","answer":"الجواب:\nنعم إذا صار في الخامس وما بعده، يُسمَّى ويُعَقّ عنه.","link":"https://binbaz.org.sa/fatwas/22003/هل-للجنين-عقيقة-اذا-نزل-ميتا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إذا نزل الجنين ميتا فهل له عقيقة.mp3","categories":["أحكام المولود"]},{"id":2575,"question":"اسم \"مَلَاك\" هل فيه شيء؟","title":"ما حكم التسمية باسم \"مَلَاك\"؟","answer":"الجواب: ما تُسمّى به المرأة، يُسمّى به الرجل، مثل ما يسمى جبريل وميكائيل.","link":"https://binbaz.org.sa/fatwas/22708/ما-حكم-التسمية-باسم-ملاك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تسمية المرأة باسم ملاك.mp3","categories":["قضايا المرأة","أحكام المولود"]},{"id":3364,"question":"إذا كان تزوج رجل امرأة ثم قُضي بينهما نسل، وبعد ذلك علم أن بينهما رضاعًا، فماذا يكون مصير الأولاد؟","title":"ما حكم أولاد زوجين تبيّن أن بينهما رضاعًا؟","answer":"الجواب: الأولاد له، أولاده، وهي محرمٌ له، تبين أنها أخته أو خالته، محرمٌ له، والأولاد له؛ للشُّبهة.","link":"https://binbaz.org.sa/fatwas/23530/ما-حكم-اولاد-زوجين-تبين-ان-بينهما-رضاعا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تزوج امرأة وقضي بينهما نسل ثم  علم أن بينهما رضاع فمامصير الأولاد.mp3","categories":["أحكام المولود"]},{"id":3435,"question":"إذا ذبح للعقيقة ثلاث أو أربع ذبائح؟","title":"هل تجوز الزيادة فوق ذبيحتين في العقيقة؟","answer":"الجواب: السنة ذبيحتان، لكن إذا كان الناس كثير، ولا يكفيهم يصير الزائد ما هو بعقيقة، العقيقة ثنتان، لكن الزائد من أجل الضيوف. السنة ثنتان فقط عن الذكر، وواحدة عن الأنثى، لكن لو كان الضيوف كثير من جيرانها، أو غيرهم، ورأى أن الثنتين لا تكفيهم، وزاد ثالثة لأجل الضيوف؛ لا بأس، من باب إكرام الضيف.\nس: إذا ذبح واحدة الآن، والأخرى فيما بعد؟\nالشيخ: ما في بأس، لا حرج، لو ذبح واحدة في اليوم السابع، وواحدة بعد يومين، أو بعد شهر، أو بعد سنة، حسب الطاقة، حسب التيسير.","link":"https://binbaz.org.sa/fatwas/23609/هل-تجوز-الزيادة-فوق-ذبيحتين-في-العقيقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/السنة في العقيقة ذبيحتان، فما حكم زيادة الذبائح.mp3","categories":["أحكام المولود"]},{"id":3802,"question":"التحنيك أليس من باب التبرك بالنبي ﷺ؟","title":"هل تحنيك المولود سنة مطلقًا أم كان للتبرك؟","answer":"الجواب: هذا خاص بالنبي ﷺ، طلب التحنيك هذا قصدهم، يريدون ما جعل الله فيه من البركة؛ لكن إذا جاب الولد لأبيه يسميه أو جاب الأخ لأخيه الكبير من باب التقدير ما في شيء.\nس: لا أنا أقصد التحنيك يا شيخ؟\nالشيخ: التحنيك سنة مطلقًا دائماً.\nس: بالتمر؟\nالشيخ: بالتمرة يمضغها الرجل ويجعلها في حنكه؛ أمه أو أبوه أو غيرهم.\nالشيخ: كله سُنة، إن سماه يوم الولادة فهو سنة، وإن سماه يوم السابع فهو سنة، كلها ثابتة عن النبي ﷺ.\nس: إذا حنك بغير التمر جائز؟\nالشيخ: السنة بالتمر.","link":"https://binbaz.org.sa/fatwas/24002/هل-تحنيك-المولود-سنة-مطلقا-ام-كان-للتبرك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/التحنيك للمولود سنة.mp3","categories":["أحكام المولود"]},{"id":3803,"question":"هل يأثم من لم يعق عن ولده؟","title":"ما حكم العقيقة والتحنيك والحلق للمولود؟","answer":"الجواب: المعروف عند جمهور أهل العلم أنها سنة؛ لقوله: من أحب أن يَعُقّ..، سنة مؤكدة.\nس: أحسن الله إليك، التحنيك للمولود سنة أو مستحب؟\nالشيخ: مستحب.\nس: يوم الولادة؟\nالشيخ: نعم، يمضغ تمرة، أمه أو أبوه، ويضعها في فمه ويدلّك الحنك الفوقي بإصبعه حتى يستقيم ويقوى ويرتفع، يعرفها الحريم.\nس: حلق الرأس، يتصدق به بوزنه؟\nالشيخ: هذا الأفضل، وزنه فضة أو ما يقوم مقامه.\nس: الذهاب به إلى المشايخ؟\nالشيخ: ما أعرف لهذا أصلًا، إنما هذا شيء يختص بالنبي عليه الصلاة والسلام، إنما التحنيك والتسمية سنة، وإذا أراد الصغير أن يقدم الكبير في التسمية يقدمه لأبيه أو لأخيه الكبير حتى يتولى التسمية، ما في مانع من باب الأدب يعني.\nس: هل يُحنّك بغير التمر؟\nالشيخ: السنة التمر، لكن إذا ما تيسر التمر، بالحلوى بالعسل، ما في بأس.","link":"https://binbaz.org.sa/fatwas/24003/ما-حكم-العقيقة-والتحنيك-والحلق-للمولود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/بعض أحكام المولود.mp3","categories":["أحكام المولود"]},{"id":4393,"question":"الجمع بين اسم النبي ﷺ وكنيته: الراجح في ذلك؟","title":"حكم الجمع بين اسم النبي ﷺ وكنيته","answer":"الجواب: لا، الصحيح أنه لا بأس به، بعد موته لا بأس، يقال: محمد أبو القاسم، إنما نهى عنه في حياته ﷺ.","link":"https://binbaz.org.sa/fatwas/24670/حكم-الجمع-بين-اسم-النبي-ﷺ-وكنيته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الراجح في الجمع بين اسم النبي وكنيته.mp3","categories":["أحكام المولود"]},{"id":4398,"question":"بعض الناس يسمي \"عزيز\" و\"حكيم\"؟","title":"ما حكم التسمِّي بـ \"عزيز\" و\"حكيم\"؟","answer":"الجواب: النبي ﷺ أقر حكيم بن حزام، وامرأة العزيز، وحكيم بن حزام معروف، وحكيم بن معاوية، لا حرج في ذلك.","link":"https://binbaz.org.sa/fatwas/24675/ما-حكم-التسمي-بـ-عزيز-وحكيم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/التسمي بعزيز وحكيم.mp3","categories":["أحكام المولود"]},{"id":4480,"question":"التَّسمية بعبدالستار وعبدالستير؟","title":"هل تجوز التَّسمية بعبد الستار وعبد الستير؟","answer":"الجواب: عبدالستير ما فيه شيء، أما عبدالستار حتى الآن ما وقفتُ على شيءٍ منه، وإن كانت مُستعملةً، والله هو الستار ، ثم لم أقف على حديثٍ فيه لفظ الستار حتى الآن.","link":"https://binbaz.org.sa/fatwas/24760/هل-تجوز-التسمية-بعبد-الستار-وعبد-الستير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/التَّسمية بعبد الستار وعبد الستير.mp3","categories":["أحكام المولود","الأسماء والصفات"]},{"id":4727,"question":"في العقيقة: لو كان للشخص ثلاثة أولادٍ فذبح لهم بعيرًا؟","title":"هل تصح العقيقة بالبعير؟","answer":"لا، السنة لا، العقيقة غنم؛ النبي ﷺ ذكر الغنم: عن الغلام شاتان، وعن الجارية شاة، السنة في العقيقة الغنم.","link":"https://binbaz.org.sa/fatwas/25036/هل-تصح-العقيقة-بالبعير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تصح العقيقة بالبعير.mp3","categories":["أحكام المولود"]},{"id":4862,"question":"بالنسبة لشروط الأضحية، والعقيقة، والهدي، هل يكون مثل بعض سواء؟","title":"هل شروط الأضحية والعقيقة والهَدي سواء؟","answer":"نعم سواء، لا يُجزئ فيها إلا الذي في الأضاحي، لا في الهدي، ولا في العقيقة، لا يُجزئ فيها إلا ما يُجزئ في الأضاحي.","link":"https://binbaz.org.sa/fatwas/25333/هل-شروط-الاضحية-والعقيقة-والهدي-سواء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/شروط الأضحية، والعقيقة، والهدي هل هي سواء.mp3","categories":["الهدي والأضاحي","أحكام المولود"]},{"id":5142,"question":"يقول هذا السائل يا سماحة الشيخ: إن تشخيص بعض الحالات المرضية للجنين يتم للمرأة الحامل، وذلك في الأشهر 4 و5 و6، وهذه الأمراض غالبًا ما تكون ذات تأثيرٍ على المريض: من تخلُّفٍ عقليٍّ، أو من تخلُّفٍ جسماني، فهل من الجائز أن يعمل إسقاط للجنين في هذه الأشهر، مع مراعاة تلك العواقب التي قد يعيش فيها الطفلُ: من التَّخلف، أو من المرض المُستديم في المجتمع؟ أفيدونا جزاكم الله خيرًا؛ لأنَّ هذه الحالة تُحيّر الأطباء.","title":"هل يجوز إسقاط الجنين إذا تبيّن أن فيه عاهة؟","answer":"الجواب: هذا موضوعٌ درسه مجلسُ هيئة كبار العلماء، وقرروا فيه قرارًا سنُعطي المدير نسخةً منه إن شاء الله، ومُلخصه أنه إذا كان الضَّرر على الطفل فهذا لا يجوز إسقاطه إذا تخلَّق أو نُفِخَتْ فيه الروح، أما إذا كان الضَّرر عليها هي -عليها خطرٌ على نفسها المرأة فقط لو تُرِكَ- والخطر يعني: الموت؛ فهذا يُسقط ولو كان في السادس أو السابع أو الثامن، إذا كان الخطر عليها، ولو بقي لهلكت هي، فهذا يُسقط. أما إذا لم يكن عليها خطرٌ فلا يُسقط؛ لأنه نوع قتلٍ، فيُترك حتى تلد، وإذا ولدت فالأمر إلى الله، إن كان سليمًا فالحمد لله، وإن كان مُشَوَّهًا فإنا لله وإنا إليه راجعون، ولا يجوز قتله. أما إذا كان قبل الأربعة أشهر فهذا إن كان فيه ضررٌ بيِّنٌ عليها جاز إسقاطه، وإن لم يكن فيه ضررٌ بيِّنٌ تُرِكَ. ونُعطي إن شاء الله المدير صورةً، فسوف يُرسَل لنا غدًا أو بعد غدٍ ونُعطيكم الصورة إن شاء الله حتى يقرأها عليكم.","link":"https://binbaz.org.sa/fatwas/30057/هل-يجوز-اسقاط-الجنين-اذا-تبين-ان-فيه-عاهة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 78.mp3","categories":["أحكام المولود"]},{"id":5153,"question":"السؤال الثاني لهذا السائل يقول: ما الحكم في إجراء الفحوصات الطبية على الجنين بغرض تشخيص بعض الأمراض الوراثية فيه وهو في بطن أمه، مع العلم أنَّ هناك دائمًا احتمالًا في التَّسبب في الإجهاض نتيجة لهذه الفحوصات؟","title":"ما حكم الفحوص الوراثية على الجنين في بطن أمه؟","answer":"الجواب: هذا فيه تفصيل: إن كانت الفحوص لا تُسبب قتله غالبًا فلا بأس، وإن غلب على الظنِّ أنها تُسبب قتله فلا تجوز، فالعمدة على الغالب:  إن كانت الفحوص التي يتعاطاها الطبيبُ مع الجنين في الغالب لا تضرُّ ولا تُوجب سقوطه ولا موته؛ فلا حرج. أما إن كان الغالبُ أنها تُسبب سقوطه وموته؛ لم تجز، فالواجب التَّحري في هذا.","link":"https://binbaz.org.sa/fatwas/30069/ما-حكم-الفحوص-الوراثية-على-الجنين-في-بطن-امه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 90.mp3","categories":["أحكام المولود"]},{"id":5219,"question":"السائل يقول: توفي والدي وأنا في الأسبوع الأول من عمري، ولا أعلم هل ذبح عقيقةً عني أم لا؟ وعند بلوغي العشرين عامًا هل يلزمني أن أعقَّ عن نفسي؟","title":"هل يجوز أن يذبح إنسانٌ عقيقة عن نفسه؟","answer":"الجواب: العقيقة سُنة في حقِّ الأب، فالأب يعقُّ عن أولاده، والعقيقة هي النَّسيكة التي تُذبح في اليوم السابع، يُسميها العامَّة: تميمة، ويُسميها بعضهم: عقيقة، والمعنى أنها ذبيحة تُذبح في اليوم السابع عن الولد: عن الذكر اثنتان، وعن الأنثى واحدة، هذه هي السُّنة، وهي سنة مُؤكدة غير واجبة، فإذا كان والدك ما عقَّ عنك فليس عليك شيءٌ، وإن ذبحت عن نفسك فلا بأس، لكنها سنَّة في حقِّ أبيك، فإذا كان ذبح فالحمد لله، وإن كان ما ذبح فليس عليك شيءٌ، وإن ذبحت أنت فلا بأس.","link":"https://binbaz.org.sa/fatwas/30163/هل-يجوز-ان-يذبح-انسان-عقيقة-عن-نفسه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 202.mp3","categories":["أحكام المولود"]},{"id":5304,"question":"نذرت لله تعالى بأن أعق جملًا إذا رزقني الله بتوأمين فهل عليّ بعد ذلك أن أعق عنهما بأي شيء آخر بعد ذلك حيث رزقت بتوأمين؟","title":"هل يُجزئ الجمل في العقيقة لمن نذره؟","answer":"الجواب: السُّنة أن تعُق عنهم بغنم، وإلا فقد نذرت فأوف بنذرك، لكن السُّنة غنم، وليس جمل، عن كل واحد رأسان من الغنم: جذع ضأن، أو ثني ماعز، هذه السنة النبي أمر أن يعق عن الغلام شاتان، وعن الجارية شاة، وإذا نذرت مع ذلك ناقة تُذبح لله فاذبحها من نذر أن يطيع الله فليطعه هكذا يقول ﷺ. السؤال: يكفيه الجمل عن الشياه؟ الشيخ: لا ما يكفيه، السُّنة الغنم.[1]","link":"https://binbaz.org.sa/fatwas/30954/هل-يجزى-الجمل-في-العقيقة-لمن-نذره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 024.mp3","categories":["أحكام المولود"]},{"id":5316,"question":"امرأة مريضة بالسكر وبضغط الدم وحامل في الشهر السابع وقال لها الأطباء إن جنينها ليس لديه جمجمة وسيموت بمجرد الولادة، فهل يجوز لها إسقاطه؟","title":"ما حكم إسقاط جنين به عاهة في الشهر السابع؟","answer":"الجواب: هذه أشياء لا ينبغي التساهل بها، فكثير من الأطباء يقررون أشياء ما لها حقيقة، ظلم وشبهات، فالواجب ترك هذا الشيء وعدم المبالاة بذلك، وسؤال الله العافية، تسأل ربها أن يعافي ولدها مما يقولون وسوف ترى الخير إن شاء الله. كثير من الأطباء يقررون أشياء وهو علقة أو مضغة أو بعد نطفة، كل هذا من التسرع وادعاء الباطل، والمدة طويلة يقلِّب الله فيها الطفل من طور إلى طور، تتغير الأحوال؛ فلا يجوز التسرع في ذلك.[1]","link":"https://binbaz.org.sa/fatwas/30978/ما-حكم-اسقاط-جنين-به-عاهة-في-الشهر-السابع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 036.mp3","categories":["أحكام المولود"]},{"id":5347,"question":"أليس من أسماء الله: النَّاصر؟","title":"ما حكم التسمِّي بـ\"عبد الناصر\"؟","answer":"الجواب: النَّصير: نِعْمَ الْمَوْلَى وَنِعْمَ النَّصِيرُ [الأنفال:40]، أما الناصر فما أعرف فيه شيئًا من الرِّوايات. س: اسم عبد الناصر؟ ج: تركه أوْلى، إذا رأى عبد النَّصير، أو عبد الملك؛ لأنَّ الناصر لا نعرفه في شيءٍ من الرِّوايات الصَّحيحة.[1]","link":"https://binbaz.org.sa/fatwas/31038/ما-حكم-التسمي-بـعبد-الناصر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fat7_majed 001.mp3","categories":["أحكام المولود","الأسماء والصفات"]},{"id":5495,"question":"التَّسمية بعبد السيد؟","title":"ما حكم التسمية بعبد السيد وعبد الموجود؟","answer":"الجواب: تركه أولى؛ لأنه يشتبه، وإلا فالسيد من أسماء الله، لكن كونه يتسمَّى بأسماء واضحة: بعبد الرحمن، بعبد العزيز، عبد السميع، عبد العليم، أولى، وإلا فالسيد مثلما قال ﷺ: السيد الله تبارك وتعالى والحديث لا بأسَ به. س: التَّسمية بعبد الموجود؟ ج: هو موجود سبحانه، لكن ليس من أسمائه الموجود. س: وإطلاق كلمة إذا نادى مثلًا يقول: يا سيد؟ ج: سيد أمرها سهل، لكن لا يقول: سيدي، تركها أفضل، \"سيد\" لا بأس، النبي ﷺ قال: إنَّ ابني هذا سيد الحسن، وكان يقول لرؤساء القبائل: مَن سيد بني فلان؟ مَن سيد بني فلان؟ يعني: مَن رئيسهم؟ ويقول في سعد بن معاذ: قوموا إلى سيدكم لما جاء يحكم في بني قريظة، يعني: رئيسهم.[1]","link":"https://binbaz.org.sa/fatwas/31404/ما-حكم-التسمية-بعبد-السيد-وعبد-الموجود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/kashf alshubuhat 008.mp3","categories":["أحكام المولود","الأسماء والصفات"]},{"id":6114,"question":"إذا كان والدي قد سماني باسم: عبدالمعطي، والعلماء اليوم منهم من ينكر الأسماء، سوى الواردة في القرآن من أسماء الله تعالى، فهل علي أن أغير اسمي إلى عبدالقدوس، أو غيره؟","title":"حكم التسمي بـ عبد المعطي","answer":"الجواب: لا، المعطي من أسماء الله، ثبت في الصحيحين من حديث معاوية، عن النبي -عليه الصلاة والسلام- أنه قال: إنما أنا قاسم، والله هو المعطي فالمعطي من أسماء الله، اسم عبدالمعطي لا بأس.","link":"https://binbaz.org.sa/fatwas/1523/حكم-التسمي-بـ-عبد-المعطي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_453.mp3","categories":["أحكام المولود","الأسماء والصفات"]},{"id":6308,"question":"..........؟","title":"حكم وليمة الختان","answer":"الجواب: لا بأس به نعمة من نعم الله، إذا جعل وليمة، وعق عنه العقيقة ذبيحتين؛ لا بأس، يدعوا إليه من أحب من إخوان سنة.  إذا كان في وقت العقيقة في اليوم السابع، أو تأخر ... بعد ذلك سنة عن الرجل ذبيحتان للذكر، وعن الأنثى واحدة، أما مجرد الختان؛ فهذا لا بأس من باب أيضاً اجتماع العائلة. السؤال: توزيع الحلوى للختان في بعض الدول المجاورة؟ الجواب: ما أعلم في هذا شيئًا، أما كونه يجعل طعامًا للختان لمن يختنه، أو لأهل الخير فرحًا بالختان بينهم، ما أعلم فيه شيئًا، كان هذا من قديم معروف، وليمة الختان من الولائم المباحة المعروفة. أما أن يفعله على طريقة خاصة يتخذها النصارى هذا ما يجوز، إن كانت الطريقة التي يفعلونها طريقة يعتادها اليهود، أو النصارى، أو كفار آخرون لا، لا يتشبه بهم تكون طريقة الختان عند المسلمين غير طريقة، أولئك تكون طريقة مختصة سليمة، لا تشبه بأعداء الله. السؤال: ختان الفتاة؟ الجواب:  سنة إذا تيسر من يعرف ذلك طيب.","link":"https://binbaz.org.sa/fatwas/1900/حكم-وليمة-الختان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_683.mp3","categories":["أحكام المولود"]},{"id":6320,"question":"التصدق بوزن الشعر فضة؟","title":"حكم حلق شعر المولود والتصدق بوزنه فضة","answer":"الجواب:  محل نظر، جاء في بعض الأحاديث عن فاطمة، لكن ما أعرف فيه سندًا جيدًا الآن، أما حلق الرأس، فهو ثابت، أما وزنه، والتصدق بزنته جاء في بعض الأحاديث التي لا أعلم صحتها يحتاج إلى إعادة نظر فيها -إن شاء الله- في حلقة أخرى غير هذه.","link":"https://binbaz.org.sa/fatwas/1902/حكم-حلق-شعر-المولود-والتصدق-بوزنه-فضة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_685.mp3","categories":["أحكام المولود"]},{"id":6329,"question":"..........؟","title":"حكم وليمة الختان","answer":"الجواب: لا بأس به نعمة من نعم الله، إذا جعل وليمة، وعق عنه العقيقة ذبيحتين؛ لا بأس، يدعوا إليه من أحب من إخوان سنة.  إذا كان في وقت العقيقة في اليوم السابع، أو تأخر ... بعد ذلك سنة عن الرجل ذبيحتان للذكر، وعن الأنثى واحدة، أما مجرد الختان؛ فهذا لا بأس من باب أيضاً اجتماع العائلة. السؤال: توزيع الحلوى للختان في بعض الدول المجاورة؟ الجواب: ما أعلم في هذا شيئًا، أما كونه يجعل طعامًا للختان لمن يختنه، أو لأهل الخير فرحًا بالختان بينهم، ما أعلم فيه شيئًا، كان هذا من قديم معروف، وليمة الختان من الولائم المباحة المعروفة. أما أن يفعله على طريقة خاصة يتخذها النصارى هذا ما يجوز، إن كانت الطريقة التي يفعلونها طريقة يعتادها اليهود، أو النصارى، أو كفار آخرون لا، لا يتشبه بهم تكون طريقة الختان عند المسلمين غير طريقة، أولئك تكون طريقة مختصة سليمة، لا تشبه بأعداء الله. السؤال: ختان الفتاة؟ الجواب:  سنة إذا تيسر من يعرف ذلك طيب.","link":"https://binbaz.org.sa/fatwas/1900/حكم-وليمة-الختان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_683.mp3","categories":["أحكام المولود"]},{"id":6732,"question":"ما هي الحكمة من العقيقة؟ ولماذا الولد اثنتان، والبنت واحدة؟ وما رأي فضيلتكم في التربية الحديثة التي تعطي الابن حرية بقصد عدم تعقيده؟","title":"المقاصد الشرعية من العقيقة","answer":"الجواب: هذه سنة شرعها الله -جل وعلا- لعباده، وسنها فينا الرسول ﷺ وشرع أن يذبح عن الغلام شاتان، وعن الجارية شاة، وقال: كل غلام مرتهن بعقيقته، تذبح عنه يوم سابعه، ويحلق، ويسمى هذا شيء شرعه الله، وبها مصالح، لا شك أنه لم يشرع عبثًا، ولا سدى، بل شرعت لحكمة بالغة، والله -جل وعلا- .. لحكمة.  وكونه للذكر ثنتين، وللأنثى واحدة لا يستغرب؛ لأن الذكر مفضل على الأنثى في إرثه لِلذَّكَرِ مِثْلُ حَظِّ الْأُنْثَيَيْنِ [النساء:11] وفي الزوج يعطى النصف في حالة عدم وجود الولد، والربع في حال الولد، والأنثى تعطى الثمن مع الولد، ومع عدمه الربع، هذا شيء معروف في الشريعة؛ لأن الذكر له شأنه، والأنثى لها شأنها، والله -جل وعلا- فاوت بين النساء والرجال في مسائل كثيرة؛  لحكمة بالغة، فعلى المؤمن أن يمتثل أمر الله، وأن يسارع إلى شرع الله، ولو لم يعلم الحكمة، فربنا حكيم عليم .","link":"https://binbaz.org.sa/fatwas/2611/المقاصد-الشرعية-من-العقيقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1107.mp3","categories":["أحكام المولود"]},{"id":6807,"question":"ماذا في الأذان، والإقامة في أذن الطفل عند بلوغه سبعة أيام؟ ما فائدة ذلك؟","title":"هل يُشرع الأذان والإقامة في أذني المولود؟","answer":"الجواب: ورد في بعض الأحاديث أنه يؤذن في اليمنى، ويقام في اليسرى، وفي سندها بعض الضعف، ولكنه من عمل المسلمين، فمن فعل ذلك؛ فلا بأس، ومن تركه؛ فلا بأس، أن يؤذن في اليمنى، ويقيم في اليسرى، اليوم السابع، ويسميه، هذا مستحب عند جمع من أهل العلم. وجاء في حديث رواه الترمذي، وصححه أن الرسول ﷺ كان يؤذن في أذن الصبي باليمنى، وجاء في حديث آخر أنه كان يقيم في اليسرى، يقول عمر بن عبدالعزيز، وجماعة من أهل العلم: أنه ينفعه هذا الشيء، قد درج عليه جمع من المسلمين، ومن ترك هذا؛ فلا بأس، فقد جاء عن النبي ﷺ أنه سمى ابنه إبراهيم لما ولد، ولم يذكر أنه أذن في أذنه اليمنى، وأقام في اليسرى، هذا يدل على التوسعة، ومن فعل ذلك؛ فلا بأس، وقد أحسن، وإن ترك ذلك؛ فلا بأس.","link":"https://binbaz.org.sa/fatwas/2704/هل-يشرع-الاذان-والاقامة-في-اذني-المولود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1203.mp3","categories":["أحكام المولود"]},{"id":6825,"question":"ماذا في الأذان، والإقامة في أذن الطفل عند بلوغه سبعة أيام؟ ما فائدة ذلك؟","title":"هل يُشرع الأذان والإقامة في أذني المولود؟","answer":"الجواب: ورد في بعض الأحاديث أنه يؤذن في اليمنى، ويقام في اليسرى، وفي سندها بعض الضعف، ولكنه من عمل المسلمين، فمن فعل ذلك؛ فلا بأس، ومن تركه؛ فلا بأس، أن يؤذن في اليمنى، ويقيم في اليسرى، اليوم السابع، ويسميه، هذا مستحب عند جمع من أهل العلم. وجاء في حديث رواه الترمذي، وصححه أن الرسول ﷺ كان يؤذن في أذن الصبي باليمنى، وجاء في حديث آخر أنه كان يقيم في اليسرى، يقول عمر بن عبدالعزيز، وجماعة من أهل العلم: أنه ينفعه هذا الشيء، قد درج عليه جمع من المسلمين، ومن ترك هذا؛ فلا بأس، فقد جاء عن النبي ﷺ أنه سمى ابنه إبراهيم لما ولد، ولم يذكر أنه أذن في أذنه اليمنى، وأقام في اليسرى، هذا يدل على التوسعة، ومن فعل ذلك؛ فلا بأس، وقد أحسن، وإن ترك ذلك؛ فلا بأس.","link":"https://binbaz.org.sa/fatwas/2704/هل-يشرع-الاذان-والاقامة-في-اذني-المولود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1203.mp3","categories":["أحكام المولود"]},{"id":7228,"question":"ما هي العقيقة؟ وما شروطها، وما صفاتها، وما وقتها؟ وهل يجوز تقسيمها مثل الأضحية إلى ثلاثة أقسام، أو أن يعملها وليمة ويجمع عليها أقاربه؟","title":"شروط العقيقة ووقتها وصفاتها","answer":"الجواب:\n\nالعقيقة يقال لها: النسيكة، ويسميها بعض الناس التميمة، وهي ذبيحة تذبح عن الولد في يوم سابعه، يقال لها: عقيقة، ويقال لها: نسيكة.\n\nوهي مثل الضحية، يعني سنها سن الضحية، جذع ضأن، أو ثني معز عن الرجل، يعني عن الذكر يذبح اثنتين، وعن الأنثى واحدة، والأفضل يوم السابع، وإن ذبحها بعد ذلك؛ أجزأت لكن الأفضل في يوم السابع.\n\nوهو مخير إن شاء قسمها على الفقراء والجيران والأقارب، وإن شاء جعلها وليمة ودعا إليها من شاء من أقاربه وجيرانه، وإن شاء قسم بعضها وأكل بعضها مع من حوله من إخوانه وجيرانه، ويسن له أن يعطي الفقراء منها ما تيسر. \n\nالسؤال: هل ممكن خاله يعق عنه، أو لازم أبوه هو الذي يعق؟\n\nالجواب: الأفضل الوالد، وإن عق غير الوالد؛ فلا بأس، الوالد هو الأفضل، هو المسؤول الأول، لكن لو عق عنه أمه، أو عق عنه أخوه، أو خاله، أو عمه؛كفى.\n\nالسؤال: والتوكيل يكفي؟ \n\nالجواب: والتوكيل يكفي.\n\nالسؤال: والتوأم يا شيخ؟ \n\nالجواب: التوأم كذلك، كل واحدة عن ثنتين، التوأم إذا كانوا ذكورًا ولدين، وإن كان ذكرًا وأنثى ثلاث، ثنتين عن الذكر، وواحدة عن الأنثى، وإن كان التوأم أنثيين؛ كفى ذبيحتان عن كل واحدة واحدة.","link":"https://binbaz.org.sa/fatwas/3283/شروط-العقيقة-ووقتها-وصفاتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1608.mp3","categories":["أحكام المولود"]},{"id":7616,"question":"هذه الرسالة بعث به المرسل (ح. ع. س) يقول في رسالته: إنه تزوج على فتاة يجهلها، ويعرف عمها وأخوها وصديقه، وبعد مضي وقت طويل لم يأته أولاد ذهب بها إلى المستشفى، وكان عندها مرض التهاب، وشفيت ولم يأتها أولاد، ففحص على نفسه، وطلعت النتيجة أن الحيوانات المنوية قليلة وغير كافية للإنجاب، ثم سافر، ولما عاد وجد زوجته في الشهر الرابع وهو يشك في هذا الحمل، ويريد التخلص من زوجته بستر، ولكن متحير ماذا يفعل نرجو الإفادة وفقكم الله.","title":"حكم الشك في نسبة الولد","answer":"الجواب: الذي يظهر لنا أن هذا يلحق به، وأن الحمل منه، وأن تقرير الأطباء لا ينبغي أن يعول عليه في هذا، بل قد يكون حملت مما حصل منه من المني وإن كان ضعيفاً، فقد جاء في الحديث: ليس من كل مني يخلق الإنسان بل من بعضه، فالحاصل أنه يلحق به لقول النبي ﷺ الولد للفراش فالرسول ﷺ ألحق الولد بالزوج وقال: الولد للفراش.\nفلا ينبغي له أن يتشكك في هذا، بل ينبغي للسائل أن يحسن الظن بأهله وأن يحمد الله على ما يسر له من الولد، ولا مانع من علاج لمزيد الأولاد، وهذا يلحق به؛ لأنه من زوجته وفي فراشه، والرسول عليه السلام قال: الولد للفراش فهذا ولده، ولا ينبغي له سوء الظن، بل ينبغي له حسن الظن بالله جل وعلا وحسن ظنه أيضاً بزوجته، وشكر الله على ما من به من الحمل، ونسأل الله له العافية والتوفيق. نعم.","link":"https://binbaz.org.sa/fatwas/4669/حكم-الشك-في-نسبة-الولد ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_023/02305.mp3","categories":["أحكام المولود"]},{"id":8784,"question":"السؤال الرابع والأخير في رسالة الأخ عباس يقول فيه: توفي لي طفل قبل حوالي خمسة عشر عاماً، وكان عمره آنذاك قد بلغ أربعة أشهر، فهل يستحق أن أعقق له، أم أضحي له، أفيدونا أفادكم الله؟","title":"حكم العقيقة عن المتوفى","answer":"الجواب: السنة أن تعق عنه شاتين إذا صار ذكرا تعق عنه شاتين، هذا هو الأفضل، وهي سنة ليست بواجبة؛ لكنها سنة، فإذا تيسر لك ذلك، فهو أفضل لك، يقول النبي ﷺ: كل غلام مرتهن بعقيقته، تذبح عنه يوم سابعه ويحلق ويسمى وأمر أن يعق عن الغلام شاتان، وعن الجارية شاة، هذا هو السنة، فإذا كنت مستطيعاً فالأفضل لك -يا أخي- أن تعق عن طفلك هذا بشاتين توزع لحمهما على إخوانك من الجيران والأقارب والفقراء، أو تطبخهما -تطبخ لحمهما- وتدعو إليه من تشاء من إخوانك وأحبابك ومن الفقراء، كله حسن، كله طيب، والحمد لله. نعم.","link":"https://binbaz.org.sa/fatwas/6946/حكم-العقيقة-عن-المتوفى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_220/22009.mp3","categories":["أحكام المولود"]},{"id":8852,"question":"أمي أنجبت بنتًا ووضعت لها اسمًا في دفتر، ونحن نناديها باسم آخر في البيت، وسمعنا أن هذا حرام، هل ما قيل لنا صحيح؟","title":"حكم تسمية الولد بغير اسمه الذي سمي به","answer":"الجواب: الذي ينبغي أن تدعى باسمها الذي سميت به، ولا تدعى بغيره، فينبغي للمؤمن أن يتقيد بالأشياء التي وضعت حتى لا يلتبس أمرها فتدعى باسمها المعروف كما تدعى باسم أبيها المعروف: ادْعُوهُمْ لِآبَائِهِمْ [الأحزاب:5] ولا تجعلوا لها اسمًا آخر تشتبه به ولا تعرف به؛ لأن الأسماء وضعت للتعريف وضبط الأمور والبيع والشراء وسائر الحقوق كلها تضبط بالأسماء، فإذا وضعتم أسماء أخرى غير الرسمية أفضى إلى الالتباس والمشاكل، فلا ينبغي ذلك، بل ينبغي أن تدعوها باسمها المعروف الذي عرفت به وصار في جوازها إن كان لها جواز، أو في حفيظتها إن كان لها حفيظة، أو في أملاكها إن كان لها أملاك، المقصود تدعى باسمها المعروف الرسمي. نعم.","link":"https://binbaz.org.sa/fatwas/7007/حكم-تسمية-الولد-بغير-اسمه-الذي-سمي-به","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_166/16609.mp3","categories":["أحكام المولود"]},{"id":8874,"question":"أخونا له سؤال أخير يقول: عند ولادة طفل أو طفلة نؤذن في أذنه اليمنى ونقيم في اليسرى، وفي اليوم السابع نقيم وليمة نشتري فيها بعض اللحم والدجاج ونعزم عليها الأصدقاء، ما هو رأيكم في هذا؟ وجهونا جزاكم الله خيرًا.","title":"ما السنة في اليوم السابع عمله للمولود؟","answer":"الجواب: السنة في هذا أن المؤمن في اليوم السابع يذبح ذبيحة من الغنم عن الأنثى وذبيحتين عن الذكر من جنس الضحية، إما ثني من المعز وإما جذع من الضأن، وتسمى العقيقة، وتسمى النسيكة، ويسميها بعض الناس التميمة، وهي سنة أمر بها النبي ﷺ، عن الذكر ثنتان وعن الأنثى واحدة، ولا يجزئ الدجاج ولا اللحم المشترى من السوق، ولكن ذبيحة تذبح إما جذع ضأن، وإما ثني من المعز، تذبح عن الأنثى واثنتان من الغنم تذبحان عن الذكر، هذا هو السنة، يطبخهما في بيته ويدعو إليهما من يشاء من أقاربه وجيرانه وأصدقائه ويوزع منها على من يشاء، هذا هو السنة وإن وزعها كلها فلا بأس. نعم.","link":"https://binbaz.org.sa/fatwas/7030/ما-السنة-في-اليوم-السابع-عمله-للمولود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_167/16703.mp3","categories":["أحكام المولود"]},{"id":9526,"question":"يسأل أيضا ويقول: رجل تزوج امرأة وبعد ستة أشهر أنجبت له طفلاً فهل المولود ابن للزوج شرعاً أم لا؟","title":"حكم نسبة الولد للزوج إذا ولد بعد ستة أشهر","answer":"الجواب: إذا كان الطفل ولد بعد ستة أشهر من وطئه لها فهو ولده؛ لأن أقل مدة الحمل ستة أشهر كما قال الله : وَحَمْلُهُ وَفِصَالُهُ ثَلاثُونَ شَهْرًا [الأحقاف:15] فستة للولد وأربع وعشرون شهراً للفطام للرضاع فأقل مدة للحمل ستة أشهر، فإذا كانت ولدته لستة أشهر بعد وطئه لها بعد نكاحه ووطئه لها فهو ولده، أما إن كان تأخر وطؤه لها وصار هذا الولد بعد الوطء بأقل من ستة أشهر وعاش ولداً كاملاً عاش فهذا محل نظر ينظر فيه؛ لأن الأصل ليس ولداً له قد حملت به قبل ذلك، إلا إذا كانت سقط ومات أو عاش مدة يسيرة ثم مات فهذا قد يكون له ويحكم له به؛ لأنه لم يعش قد يكون لخمسة وقد يكون لأربعة وأيام فلا يعيش وإن صرخ ولكنه لا يعيش في الغالب، إنما الذي يعيش ابن ستة أشهر فأكثر هذا هو المعروف عند أهل العلم.\nفالحاصل أنه إذا سقط لستة أشهر ولم يعش وإن سقط حياً ثم مات فإنه لا يجزم بأنه من غيره ولا يحكم عليها بأنها زنت لأن ما دون الستة الأشهر ممكن إذا كان لم يعش.. من سقط صغيراً ولم يعش فإنه قد يكون من وطئه الذي حصل بعد النكاح إذا مضى عليه أكثر من أربعة أشهر، أما إذا عاش وهي أتت به إلى قبل ستة أشهر فهذا دليل على أنها حامل قبل أن ينكحها فيكون النكاح باطلاً وينظر في أمرها بعد ذلك. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7698/حكم-نسبة-الولد-للزوج-اذا-ولد-بعد-ستة-اشهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_245/24510.mp3","categories":["أحكام المولود"]},{"id":9692,"question":"هذه رسالة من موسى محمد موسى من السودان من الخرطوم، وهي رسالة غريبة في الحقيقة يقول: لو أن رجلاً متزوج وخرج من منزله ذات يوم، فجاءت امرأة ضيفة على أهله، ولم يكن هو على علم بها، وعاد إلى البيت في وقت متأخر من الليل فأراد أن يجامع أهله فأخطأ وجامع هذه الضيفة وأنجبت منه طفلاً، فهل هذا الطفل ممكن أن يرث هذا الرجل أم لا، أفيدوني أفادكم الله؟","title":"حكم إلحاق الولد في وطء الشبهة","answer":"الجواب: إذا كان الواقع صحيحاً وأنه شبهة، وأنه غلط، فإن الولد يكون ولده يلحق بالشبهة، مثل لو عقد على امرأة فأدخل عليه غيرها وظن أنها الزوجة، فجامعها فإن ولدها يلحق به؛ لأنه وطء بشبهة.\nأما إن كان كاذباً وأنه جامعها ويعلم أنها غير امرأته، هذا زنا والولد لا يلحق به؛ لأنه زنا، أما إذا كان غلط وجامعها يحسب أنها زوجته؛ لأسباب لظلمة، أو لأسباب أخرى والله يعلم ما في القلوب ولا يخفى عليه خافية سبحانه وتعالى، إذا كان عن شبهة فإن الولد يلحقه، وعليها هي الاستبراء، فليس لها أن تتزوج إلا بعد الاستبراء .....، لكن ما دام حملت منه فإن عدتها وضع الحمل، متى وضعت الحمل خرجت من عدتها. نعم.\nالمقدم: بارك الله فيكم، ألا ينبغي التحرز من جانب المسلمين والحذر من مثل هذه الأمور؟\nالشيخ: لا شك أن هذا يجب التحرز منه وهذا من النوادر، من أندر النوادر؛ لأن الغالب أن الرجل يعرف زوجته ولا تشتبه عليه، فهذا من أندر النوادر. نعم.","link":"https://binbaz.org.sa/fatwas/7904/حكم-الحاق-الولد-في-وطء-الشبهة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_254/25413.mp3","categories":["أحكام المولود"]},{"id":9694,"question":"هذه رسالة من موسى محمد موسى من السودان من الخرطوم، وهي رسالة غريبة في الحقيقة يقول: لو أن رجلاً متزوج وخرج من منزله ذات يوم، فجاءت امرأة ضيفة على أهله، ولم يكن هو على علم بها، وعاد إلى البيت في وقت متأخر من الليل فأراد أن يجامع أهله فأخطأ وجامع هذه الضيفة وأنجبت منه طفلاً، فهل هذا الطفل ممكن أن يرث هذا الرجل أم لا، أفيدوني أفادكم الله؟","title":"حكم إلحاق الولد في وطء الشبهة","answer":"الجواب: إذا كان الواقع صحيحاً وأنه شبهة، وأنه غلط، فإن الولد يكون ولده يلحق بالشبهة، مثل لو عقد على امرأة فأدخل عليه غيرها وظن أنها الزوجة، فجامعها فإن ولدها يلحق به؛ لأنه وطء بشبهة.\nأما إن كان كاذباً وأنه جامعها ويعلم أنها غير امرأته، هذا زنا والولد لا يلحق به؛ لأنه زنا، أما إذا كان غلط وجامعها يحسب أنها زوجته؛ لأسباب لظلمة، أو لأسباب أخرى والله يعلم ما في القلوب ولا يخفى عليه خافية سبحانه وتعالى، إذا كان عن شبهة فإن الولد يلحقه، وعليها هي الاستبراء، فليس لها أن تتزوج إلا بعد الاستبراء .....، لكن ما دام حملت منه فإن عدتها وضع الحمل، متى وضعت الحمل خرجت من عدتها. نعم.\nالمقدم: بارك الله فيكم، ألا ينبغي التحرز من جانب المسلمين والحذر من مثل هذه الأمور؟\nالشيخ: لا شك أن هذا يجب التحرز منه وهذا من النوادر، من أندر النوادر؛ لأن الغالب أن الرجل يعرف زوجته ولا تشتبه عليه، فهذا من أندر النوادر. نعم.","link":"https://binbaz.org.sa/fatwas/7904/حكم-الحاق-الولد-في-وطء-الشبهة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_254/25413.mp3","categories":["أحكام المولود"]},{"id":9830,"question":"وأولى رسائل هذه الحلقة وردتنا من الجمهورية العربية اليمنية من سائل سمى نفسه عبدالرحمن الحسين علي ، هذه الرسالة يقول السائل: كنت مغتربًا فترة عام خارج البلاد ثم عدت في إجازتي السنوية، وباشرت حياتي الزوجية مع زوجتي، وبعد انقضاء الإجازة عدت إلى عملي في خارج بلادي، وبعد شهرين وصلني خطاب علمت منه بأن زوجتي حبلى وكان الخطاب منها، وبعد انقضاء فترة سبعة أشهر وخمسة أيام من تاريخ أول جماع بيني وبينها وصلتني برقية بأن زوجتي أنجبت مولودًا ذكرًا، وقد دخلني الشك في ذلك، وعند عودتي في الإجازة في السنة الأخرى سألتها وعلمت منها بأنها أصيبت بألم وتعبت جدًا؛ وكان ذلك سبب الولادة المبكرة، وفعلًا الألم والمرض حصلا لها ورغم ذلك لم أقتنع، ومما زاد في شكي تعليق بعض الأقارب على هذه الحادثة، وأنا في حيرة من أمري وأريد أن أعرف الآتي: ما هي العلامات والدلائل التي يعرف بها مولود السابع؟ وهل يجوز لي أن أحلفها بالله على شرفها وعفتها وأصدقها وبعد أن تحلف أكتفي بذلك؟ أم ما هي الطريقة الشرعية الصحيحة للخلاص من هذه المشكلة؟","title":"حكم شك الرجل بأهله بسبب الولادة المبكرة","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فهذه المسألة أيها الأخ السائل ليس فيها بحمد الله إشكال، فقد بين الله عز وجل أن الولد مدته التي لابد منها ستة أشهر في الرحم، وبعدها قد تلده المرأة في الشهر السابع وبعد ذلك، وهذه ولدت لسبعة أشهر وخمسة أيام فليس فيها إشكال ولا ينبغي أن ترتاب فيها، وينبغي لك أن تحسن الظن بأهلك ما لم تر شيئًا واضحًا بعينك أو تسمع بأذنك، أما التهم التي لا أساس لها فلا ينبغي للمؤمن ذلك؛ بل ينبغي للمؤمن أن ينزه سمعه وبصره ودينه عما لا يليق، وإحسان الظن بالزوجة أمر واجب ما لم يوجد ما يخالف ذلك بصفة لا شك فيها ولا شبهة.\nوينبغي لك أن تطمئن وأن الولد ولدك، وأن تحسن ظنك بأهلك، وأن تدع وساوس الشيطان، رزقنا الله وإياك الاستقامة.\nومن الأدلة ما ذكرنا قوله جل وعلا في المولود: وَحَمْلُهُ وَفِصَالُهُ ثَلاثُونَ شَهْرًا [الأحقاف:15]، فجعل الحمل والفصال ثلاثين شهرًا، وأخبر في آية أخرى أن فصاله في عامين، قال: وَفِصَالُهُ فِي عَامَيْنِ [لقمان:14]، فدل ذلك على أن حصة الحمل ستة أشهر، وحصة الولد بعد الولادة أو قبل الفطام سنتان؛ عامان فقط، فإذا ذهب أربعة وعشرون شهرًا بقي ستة أشهر للحمل، وبهذا تعلم أن ولادتها له بعد أول جماع لسبعة أشهر وخمسة أيام أنه شيء لا شبهة فيه ولا شك فيه والحمد لله. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7995/حكم-شك-الرجل-باهله-بسبب-الولادة-المبكرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_198/19801.mp3","categories":["أحكام المولود"]},{"id":10123,"question":"ما حكم العقيقة وما هو وقتها، وإذا فات وقت العقيقة فمتى يعق عن المولود؟ وإذا كبر المولود وشب ولم يعق عنه فهل يعق عنه وهو كبير؟","title":"حكم العقيقة وبيان وقتها","answer":"الجواب: العقيقة سنة مؤكدة، وهي ذبيحتان عن الرجل وذبيحة واحدة عن الأنثى، كما أمر النبي ﷺ: أن يعق عن الغلام شاتان وعن الجارية شاة ووقتها يوم السابع، هذا هو الأفضل، في اليوم السابع وإن ذبحت بعد ذلك فلا حرج ولو بعد سنة أو سنتين، وإذا لم يعق عنه أبوه وأحب أن يعق عن نفسه فهذا حسن، هي مشروعة في حق الأب، لكن لو عق عن نفسه أو عقت عنه أمه أو أخوه فلا بأس، كله حسن إن شاء الله، وليس لها وقت محدود، ولو بعد سنة أو سنتين ولو كان كبيرًا، لكن السنة أن يعق الأب عن ولده في يوم السابع هذا هو السنة.\nالمقدم: جزاكم الله خيرا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8294/حكم-العقيقة-وبيان-وقتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_277/27710.mp3","categories":["أحكام المولود"]},{"id":10240,"question":"المستمع (ع. ف. ي) بعث يسأل ويقول: لي ثلاثة أبناء بنت وولدان لم أعمل لهم عقيقة بسبب ظروفي المادية، وكنت أسكن في منطقة لا أعرف فيها أحد، والآن الحمد لله تحسنت أحوالي فكيف توجهونني في هذا الأمر، وهل أوزع العقيقة على الفقراء أم أجعلها كوليمة وأدعو عليها الأصدقاء والجيران، وجهوني جزاكم الله خيرًا؟","title":"بعض أحكام العقيقة","answer":"الجواب: العقيقة سنة مؤكدة عن الذكر ثنتان من الغنم كالضحية سنها سن الضحية، وعن الأنثى واحدة تذبح يوم السابع إذا تيسر ذلك، فإن لم يتيسر ذبحها متى تيسرت، وإذا تيسر لك الآن ذبح العقيقة فالحمد لله اذبحها الآن ولك أن تتصدق بها، ولك أن تتصدق ببعضها، ولك أن تطبخها وتدعو عليها الأقارب والجيران كل هذا واسع والحمد لله الأمر فيها واسع.\nالمقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8411/بعض-احكام-العقيقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_278/27813.mp3","categories":["أحكام المولود"]},{"id":10655,"question":"هذا السائل (سعد . ن. ع. الدوسري ) من الرياض يقول: هل التميمة تجب على الفقير والغني؟ وهل يجب على والد المولود أن يدفع قيمة هذه التميمة، أم يشتريها الجد، أم ماذا؟! جزاكم الله خيرًا.","title":"هل العقيقة تجب على الفقير والغني؟","answer":"الجواب: التميمة هي العقيقة، وهي النسيكة، يسمونها العامة بعضهم يسمونها التميمة وهي سنة عن الرجل وعن المرأة، عن الذكر ثنتان، يعني: رأسان من الغنم سواءً ضأن وإلا ماعز، ذكور وإلا إناث، وعن الأنثى واحدة، هذا السنة تذبح يوم السابع عن الذكر ثنتان يوم السابع، وعن الأنثى واحدة، هذا هو الأفضل، يذبحها الوالد سنة في حق الأب غير واجبة ما هي بواجبة لكن سنة في حق الأب، والجد يقوم مقامه إذا كان ما هو موجود، وإن ذبحتها الأم كفى، نعم.\nوإذا لم يذبحها اليوم السابع ذبحها بعد ذلك، ......... الرابع عشر في الحادي والعشرين فيما بعد ذلك لا بأس، ولو بعد سنة أو سنتين، إذا تيسر لهما ذلك، لكنها مستحبة غير واجبة سنة مؤكدة.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8832/هل-العقيقة-تجب-على-الفقير-والغني","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_285/28517.mp3","categories":["أحكام المولود"]},{"id":10868,"question":"يقول: رزقت بثلاث بنات، وذبحت لكل بنت شاة حين ولادتها، ولكن لم أقل هذه عقيقة للبنت حيث كنت لا أعلم أن العقيقة واجبة، سؤالي: هل تجزئ هذه الذبائح عن العقيقة؟ ولو كنت أعلم أن العقيقة واجبة لقلت حين ذبحها: هذه عقيقة البنت.","title":"حكم التلفظ بالنية عند ذبح العقيقة","answer":"الجواب:  النية كافية، ولا حاجة إلى أن تقول عقيقة، النية كافية، والعقيقة سنة، وليست واجبة، فأنت بحمد الله قد أديت السنة والحمد لله، والنية كافية في هذا إذا نوى بالذبيحة عن ابنته، أو الذبيحتين عن ولده الذكر كفى ذلك، وإن لم يتلفظ بشيء، وإن قال: هذه عن ولدي فلان، أو عن بنتي فلانة، فلا بأس كالضحية، كونه يقال: هذه ضحية عن فلان، أو اللهم تقبل من فلان، كله لا بأس به، كله طيب، ولكن النية كافية ولو لم يتلفظ بشيء لقول الرسول ﷺ: إنما الأعمال بالنيات، وإنما لكل امرئ ما نوى، فالنية التي محلها القلب ثابت في هذا والحمد لله. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9034/حكم-التلفظ-بالنية-عند-ذبح-العقيقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_357/35702.mp3","categories":["أحكام المولود"]},{"id":11063,"question":"يقول: كان لي أربعة أولاد إلا أنهم توفوا وهم صغار، بعضهم أثناء الولادة وواحد منهم بعدما بلغ أربعين يوماً، ولم أتذكر العقيقة عنهم إلا أنني سمعت الآن عن وجوبها، فهل أقضيها الآن؟","title":"حكم قضاء العقيقة","answer":"الجواب:  سنة غير واجبة، سنة مؤكدة، وإن فعلتها فهو أحسن، إن قضيتها فهو أحسن، فعلاً للسنة جزاك الله خيرًا.  المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9240/حكم-قضاء-العقيقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_367/36713.mp3","categories":["أحكام المولود"]},{"id":11142,"question":"السائل عبدالله صالح يقول في هذا  أرجو من سماحة الشيخ الإجابة على سؤالي وهو: هل يجوز حلق رأس المولود إذا كان أنثى؟","title":"حكم حلق رأس الأنثى المولودة","answer":"الجواب:  الأنثى لا يحلق رأسها، لكن إذا إنسان من باب الطب لمرض لا بأس، وإلا لا يحلق رأسها حتى في الحج والعمرة يقص منه قصًا، تقصير؛ لأن أصل الرأس للمرأة جمال، أما إذا كان لعلة مرض، رأى الأطباء، رأى الطبيب المختص، أو الطبيبة المختصة أن الحلق هو العلاج فلا بأس، نعم.","link":"https://binbaz.org.sa/fatwas/9321/حكم-حلق-راس-الانثى-المولودة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_290/29013.mp3","categories":["أحكام المولود"]},{"id":11254,"question":"تقول: أنا امرأة حملت وفي الشهر الثالث وزيادة أسبوع سقط الجنين، وأنا لا أعلم ما نوع الجنين، قال لي بعض الناس: يجب عليك تسمية هذا الجنين والذبح له، وأنا لا أعلم الحكم في ذلك الوقت، ولم أفعل شيئًا فبماذا توجهونني، وهل تجب التسمية والحال ما ذكر، وهل يجب الذبح جزاكم الله خيرًا؟","title":"من أحكام السقط","answer":"الجواب:  إذا كان الجنين سقط قبل أربعة أشهر، فلا يسمى وليس له عقيقة، إنما العقيقة والتسمية لمن سقط في الخامس أو بعده ممن نفخ فيه الروح؛ لأنه يكون آدميًا له حكم الأفراط، فيذبح عنه ويسمى ويغسل ويصلى عليه إذا سقط في الخامس فما بعده بعد نفخ الروح فيه. أما ما يسقط في الرابع أو في الثالث هذا ليس له حكم الأفراط، لكن إذا كانت الخلقة بينة فيه، يعني: قد تبين فيه صفات آدمي من رأس أو يد أو رجل أو نحو ذلك، يكون لأمه حكم النفاس لا تصلي ولا تصوم، وأما هو فليس له حكم الموتى وليس له حكم الأجنة بل يدفن في أي مكان ويكفي ولا يغسل ولا يصلى عليه؛ لأنه لا يكون آدميًا ولا يكون له حكم الأموات إلا إذا كان قد نفخت فيه الروح في الخامس وما بعده. أما إذا مات في الرابع أو في الثالث، إذا سقط في الرابع أو في الثالث إنما هو لحمة قد بان فيها خلق الإنسان من رأس أو رجل أو نحو ذلك فإنها لا تصلي ولا تصوم، مدة النفاس أربعين يوم فأقل، ومتى طهرت في الأربعين صلت وصامت، وإذا تمت الأربعين اغتسلت وصلت ولو معها دم، دمها يكون دم فساد، بعد الأربعين دم فساد، تصلي وتصوم وتتوضأ لكل صلاة كالمستحاضة. أما إن طهرت في الأربعين فإنها تغتسل وتصلي وتصوم وتحل لزوجها. أما إن كان دمًا لم يتبين فيه شيء يعني قطعة لحم، أو دم ما بان فيها شيء فهذا دم فاسد لا تدع الصلاة ولا الصوم ولا تحرم على زوجها، إذا كانت اللحمة التي سقطت ليس فيها خلق الإنسان، لا رأسًا ولا رجلًا ولا يدًا ما بان شيء ولا اتضح شيء، فإن هذا الدم لا يعتبر وعليها أن تصلي وتصوم وتحل لزوجها، وتتوضأ لكل صلاة إن كان معها دم، تتوضأ لكل صلاة كسائر الدماء الفاسدة كالمستحاضة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9433/من-احكام-السقط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_374/37406.mp3","categories":["أحكام المولود"]},{"id":11255,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين آثر فيها عدم ذكر اسمه، أخونا يسأل جمعًا من الأسئلة في أحدها يقول: ما حكم عدم حلق شعر المولود في الأسبوع، وتربية هذا الشعر إلى ما شاء الله، جزاكم الله خيرًا؟","title":"استحباب حلق شعر المولود يوم سابعه","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد. فقد ثبت عن النبي ﷺ أنه قال: كل غلام مرتهن بعقيقته تذبح عنه يوم سابعه ويحلق ويسمى، فالسنة حلق رأسه يوم السابع هذه السنة، والتسمية كذلك والعقيقة، وهي شاتان في حق الذكر، وشاة واحدة في حق الأنثى، هذا هو السنة فينبغي العمل بها وتنفيذها. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9428/استحباب-حلق-شعر-المولود-يوم-سابعه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_374/37401.mp3","categories":["أحكام المولود"]},{"id":11382,"question":"مستمع بعث برسالة يقول: أخوكم في الله محمد حسن عز الدين مصري ومقيم في المملكة، يسأل سماحتكم ويقول: لي ثلاثة من الأبناء لم أذبح عند ولادتهم العقيقة اتباعًا لسنة رسولنا الكريم ﷺ، حيث أنني لم أكن أعلم بوجوبها، وبعد علمي والحمد لله لم يتيسر لي الحال للقيام بها، فهل أستطيع أداءها إذا تيسر الحال بالرغم من بلوغ أولادي سن التاسعة عشر؟ وإذا فرض هذا فهل يأكل منها أهل البيت أم توزع كلها على الفقراء؟ جزاكم الله خيرًا.","title":"حكم العقيقة، وحكم ذبحها عن الابن بعدما يكبر","answer":"الجواب:  العقيقة مستحبة تذبح يوم السابع عن الذكر ثنتان وعن الأنثى واحدة، وإذا لم تذبح فلا شيء عليك، وإن ذبحت ولو بعد الكبر فذلك أفضل، والسنة أن تأكل منها أنت وأهل بيتك وتطعم من ترى من جيرانك والفقراء، وإن فرقتها بين الفقراء كلها أو بعضها فلا بأس، وإن أكلتها كلها أنت وأهل بيتك فلا بأس، ولكن الأفضل أن تطعم وتتصدق وتأكل. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9568/حكم-العقيقة-وحكم-ذبحها-عن-الابن-بعدما-يكبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_379/37915.mp3","categories":["أحكام المولود"]},{"id":11831,"question":"إذا أسقطت المرأة حملها قبل أن تنفخ فيه الروح، هل هذا السقط ينفع والديه يوم القيامة؟ جزاكم الله خيرًا.","title":"السقط الذي يعتبر طفلاً","answer":"الجواب:  قبل أربعة أشهر لا يسمى ولدًا، إنما يسمى ولدًا بعد الأربعة بعد نفخ الروح فيه، يغسل، ويصلى عليه، ويعتبر طفلًا ترجى شفاعته لوالديه، أما قبل ذلك فليس بإنسان، وليس بميت، ولا يعتبر طفلًا، ولا يغسل، ولا يصلى عليه، ولو كان لحمة فيها تخطيط، ولا يجوز لها إسقاطه، ليس للمرأة أن تسقطه إلا في الأربعين الأولى إذا دعت الحاجة إلى ذلك، كالعزل في الأربعين الأولى؛ لا بأس إذا دعت الحاجة إلى هذا الشيء، المصلحة الشرعية. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10004/السقط-الذي-يعتبر-طفلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_395/39507.mp3","categories":["أحكام المولود"]},{"id":11888,"question":"تسأل سماحتكم عن السقط، هل له عقيقة، أو لا؟ وتذكر أنه يحصل ذلك معها في الشهر الرابع والخامس، أو في الثالث أحيانًا، جزاكم الله خيرًا.","title":"حكم تسمية السقط والعق عنه","answer":"الجواب:  إذا كان السقط في الخامس، أو ما بعده قد نفخت فيه الروح؛ فيسمى، ويعق عنه أفضل، ليس بواجب، لكن الأفضل أن يعق عنه ويسمى، أما إن كان السقط في الرابع وما قبله؛ فليس له تسمية، ولا يسمى ولدًا، ولا يصلى عليه، يدفن في أي بقعة، ولا يعق عنه؛ لأنه ما بعد تم خلقه، ولا نفخت فيه الروح؛ فلا يكون فرطًا، الفرط هو الذي يولد في الخامس فما بعده .... نفخ الروح فيه، فهذا يستحب أن يسمى، وأن يعق عنه إذا كان ذكرًا؛ يعق عنه بذبيحتين، وإن كان أنثى؛ بواحدة من الغنم، هذا هو السنة الثابتة عن النبي -عليه الصلاة والسلام- نعم.","link":"https://binbaz.org.sa/fatwas/10072/حكم-تسمية-السقط-والعق-عنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_425/42509.mp3","categories":["أحكام المولود"]},{"id":11915,"question":"من أبي الوليد عبدالملك بن علي بن هادي المرادي رسالة وضمنها جمعًا من الأسئلة يقول في أحدها: نشاهد الكثير من الناس يكتبون لفظ الجلالة الله على جبين المولود بالكحل، فهل هذا جائز؟ وهل يجوز الاحتفال بالمولود بعد مرور سبعة أيام من ولادته؟ وهذا ما يسمونه: بالسبوع جزاكم الله خيرًا.","title":"حكم كتابة اسم الله على جبين المولود وحكم السبوع","answer":"الجواب:  لا يجوز كتب أسماء الله على الولد، ولا غير الولد، ولا على الملابس، ولا على الفرش؛ تنزيهًا لاسم الله، واحتراماً له، أما الاحتفال بالمولود يوم السابع بالعقيقة كون تصنع وليمة من أجل العقيقة؛ هذا مستحب، يصنعون عقيقة، ويدعون من شاؤوا من أقاربهم، ومن جيرانهم، ويأكلون ويطعمون سنة، عن الذكر ثنتان ذبيحتان من الغنم، وعن الأنثى واحدة يوم السابع أفضل، وإن ذبحوها بعد ذلك؛ فلا بأس، لكن اليوم السابع أفضل يأكلون ويطعمون، وإن وزعوها كلها أو بعضها؛ فلا بأس. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10099/حكم-كتابة-اسم-الله-على-جبين-المولود-وحكم-السبوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_426/42616.mp3","categories":["أحكام المولود"]},{"id":11994,"question":"هل هو حرام قص شعر المولودة، أم أنه جائز؟","title":"حكم قص شعر المولودة","answer":"الجواب:  المولودة لا يقص شعرها، ولا يحلق إنما هو الرجل، الصبي الصغير يحلق يوم السابع، أما الجارية لا، لا تحلق، إلا إذا كان للدواء، إذا كان في رأسها مرض، وحلق للدواء؛ فلا بأس. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10179/حكم-قص-شعر-المولودة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_431/43108.mp3","categories":["أحكام المولود"]},{"id":12795,"question":"يسأل سؤالًا آخر ملخصه يقول: حدثونا عن العقيقة وأحكامها، وما حكم تأخيرها، ومن الذي يجوز له الأكل منها، ومن الذي لا يجوز؟","title":"بيان القول في العقيقة","answer":"الجواب:  العقيقة هي الذبيحة التي تذبح عن المولود، عن الذكر ثنتان، وعن الأنثى واحدة، سنة مؤكدة، أمر بها النبي ﷺ والأفضل أن تذبح يوم السابع، هذا هو الأفضل، وروي عن عائشة -رضي الله عنها- ذبحها في أربعة عشر، وإحدى وعشرين، ولكن الأفضل يوم السابع، هذا هو الأفضل، فإن لم يتيسر ذلك، وذبح في الرابع عشر، أو في الحادي والعشرين، كما قالت عائشة فحسن، وإن ذبح في غيرهما؛ فلا بأس ليس لها حد محدود بعد السابع، إذا ذبحها بعد أسبوع، في اليوم السابع، أو بعد أسبوعين، أو بعد شهر، أو شهرين، أو أكثر؛ فلا حرج، ليس لذلك حد، بل السنة أنه يذبحها ولو تأخرت، يذبحها الوالد أبو الطفل، السنة في حق الوالد أن يذبحها، ولو بعد الأسبوع، لكن الأفضل أنه يتحرى يوم السابع، هذا هو الأفضل. وحكمها أنها سنة، ليست واجبة، يأكل منها، ويطعم يطعم أقاربه، أو جيرانه، أو يوزعها على الفقراء، أو يأكل بعضها ويوزع بعضها، أو يصنع وليمة، ويدعو إليها، كل ذلك حسن والحمد لله. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11009/بيان-القول-في-العقيقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_461/46115.mp3","categories":["أحكام المولود"]},{"id":13002,"question":"تذكر في هذا السؤال هذه السائلة، وتقول: هل يجوز تسمية الابن المولود على اسم أخيه المتوفى، أم يجب أن نختار له اسمًا آخر؟","title":"حكم تسمية المولود باسم أخيه المتوفى","answer":"الجواب:  لا حرج، قد يسمى المولود باسم أخيه المتوفى، ولا حرج في ذلك، والحمد لله، نعم.","link":"https://binbaz.org.sa/fatwas/11219/حكم-تسمية-المولود-باسم-اخيه-المتوفى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_504/50415.mp3","categories":["أحكام المولود"]},{"id":13257,"question":"السائل محمد عبدالله الغنام يقول في سؤال له: هل ما ينطبق على. الشيخ: محمد عبدالله أيش؟المقدم: محمد عبدالله الغنام.الشيخ: نعم.المقدم: يقول في سؤال له سماحة شيخ: هل ما ينطبق على الأضحية من شروط ينطبق على العقيقة؟","title":"من أحكام العقيقة","answer":"الجواب:  نعم، كما أنه لا يضحى بالعرجاء والمريضة والهزيلة والعوراء، كذلك في العقيقة لا يعق بالهزيلة، ولا بالعرجاء، ولا بالمريضة، ولا بالعوراء، أو العمياء، ما يجوز، لابد تكون سليمة، نعم. كالضحية سواء. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11543/من-احكام-العقيقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_514/51402.mp3","categories":["أحكام المولود"]},{"id":14562,"question":"المستمع (م. ن) بعث يسأل عن العقيقة، ويقول: هل هي واجبة أو لا؟ إذ أني أنجبت أربعة أطفال بنتين وولدين، ولم أعمل عن أحد منهم عقيقة، هل هي واجبة فأقضيها الآن، أم كيف توجهونني؟جزاكم الله خيرًا.","title":"هل العقيقة واجبة؟","answer":"الجواب: العقيقة سنة مؤكدة، أمر بها النبي ﷺ وفعلها، فالسنة للمؤمن أن يعق عن أولاده، عن الذكر ثنتان، وعن الأنثى واحدة من الغنم، هذا السنة، والعقيقة مثل الضحية جذع الضان، أو ثني معز، وليست واجبة، ولكنها سنة مؤكدة، فيشرع لك -أيها السائل- أن تعق عن أولادك الأربعة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13059/هل-العقيقة-واجبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_489/48912.mp3","categories":["أحكام المولود"]},{"id":14669,"question":"المستمع عثمان موسى محمد آدم بعث برسالة يقول فيها: لي مجموعة من الأولاد، لم أعمل لهم العقيقة، وسمعت حديثًا يقول: كل مولود رهين بعقيقته حتى تعطى عنه .أرجو أن توجهوني، جزاكم الله خيرًا.","title":"حكم العقيقة عن المولود","answer":"الجواب: نعم الحديث صحيح، وعليك أن تعق عن أولادك، ثم هي سنة مؤكدة، فإذا استطعت أن تعق عنهم عن كل واحد شاتان إذا كان ذكرًا، وعن كل أنثى شاة، تذبح وتأكل منها أنت وأهلك وتوزع على جيرانك والفقراء، أو تذبحها وتوزعها على الفقراء، أو تجمع عليها بعض جيرانك وأقاربك مع الصدقة على بعض الفقراء كله حسن -إن شاء الله-، وهي سنة مؤكدة؛ لقوله ﷺ: كل غلام مرتهن بعقيقته تذبح عنه يوم سابعه، ويحلق ويسمى ولأنه ﷺ أمر عن الغلام شاتان، وعن الجارية شاة. فالواجب العناية بهذه السنة، وأن تنفذ كما شرعها الله، والأفضل أن تكون يوم السابع إذا تيسر ذلك، فإن لم يتيسر ففي أربعة عشر، فإن لم يتيسر ففي إحدى وعشرين، كما جاء ذلك عن عائشة -رضي الله عنها-، فإذا لم يتيسر ففي أي وقت، وتقدم أنها سنة مؤكدة، وليست بواجبة وجوب الفرائض، ولكنها مؤكدة، هذا هو المختار فيها. فالواجب أن تؤدى على الوجه الشرعي، يؤديها المؤمن على الوجه الشرعي، عن الذكر ثنتان، وعن الأنثى شاة، وإذا عجز صار يعجز عن ثنتين ذبح واحدة: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] هذا هو الأفضل، ليس آثمًا لو ترك لا يأثم بذلك؛ لأنها ليست فرضًا، وإنما سنة مؤكدة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13177/حكم-العقيقة-عن-المولود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_628/nour_62806.mp3","categories":["أحكام المولود"]},{"id":15107,"question":"السؤال الأخير في لقائنا هذا، وردنا من حفر الباطن، من إبراهيم المحمد البكار، يقول: سمعنا أن الحرمة إذا وضعت الوليد يقولون قبل أن يرضع لازم يؤذن في أذنه، ويأخذ تمرة، ويوضع في فم المؤذن، ويوضع المؤذن لسانه في فم الولد، وبعد ذلك يقص من شعر الطفل هل هذا صحيح أو بدعة؟","title":"حكم تحنيك الطفل والأذان في أذنيه وحلق رأسه","answer":"الجواب: هذا على ما ذكره السائل غير صحيح، ما ذكره السائل على هذا الوجه الذي ذكره غير صحيح، ولكن يستحب في اليوم السابع، في اليوم السابع يستحب أنه يؤذن في أذنه اليمنى، ويقام في اليسرى، ويسمى في اليوم السابع، ولا بأس، يستحب التحنيك بالتمر، بأن يوضع تمر، يضع التمر الإنسان في فمه أو أمه تضع في فمها، ثم تمجه في فم الصبي، التمرة، كما فعله النبي ﷺ، وأما أن يدخل لسانه في فم الصبي، لا، لكن يمجه في فم الصبي، ويكفي، شيء قليل يناسب الصبي الصغير، أو البنت الصغيرة. وأما الأذان فيكون في اليوم السابع، وإن ترك ذلك فلا بأس، النبي ﷺ لم يثبت عنه أنه أذن في أذن الصبي أو الصبية، ولكن جاء عنه في بعض الأحاديث التي فيها بعض الضعف الأذان في أذن الصبي، والإقامة في اليسرى من أذنيه، فإذا فعله الإنسان فلا بأس، وقد فعله عمر بن عبدالعزيز وجماعة من أهل العلم، لا بأس، وإن ترك ذلك وسماه بدون أذان ولا إقامة فلا بأس، قد سمى النبي ﷺ ابنه إبراهيم بدون أذان وإقامة، وسمى بعض أولاد الصحابة في اليوم السابع بدون أذان وإقامة، وسمى بعضهم في اليوم الأول، وسمى ابنه في اليوم الأول، ولا حرج في هذا، لا بأس أن يسمى في اليوم الأول، أو في اليوم السابع، ولا بأس أن يؤذن في أذنه اليمنى، ويقام في اليسرى، لا حرج في ذلك، والسنة أن يسمى في اليوم الأول، أو في اليوم السابع، هذه السنة. أما العقيقة فيكون في اليوم السابع، يعق عنه في شاتين إن كان ذكرًا، أو بشاة واحدة إن كان أنثى في اليوم السابع، إن شاء ذبحها وأكلها وأهل بيته، هو وأهل بيته ونحو ذلك، وإن شاء وزعها بين الجيران والفقراء، وإن شاء أكل بعضها، وفرّق بعضها، كله واسع بحمد الله، وهكذا يحلق الصبي شعره، يحلق رأس الصبي الذكر، هذا هو السنة؛ لقول النبي ﷺ: كل غلام مرتهن بعقيقته، تذبح عنه يوم سابعه، ويحلق ويسمى هكذا جاء الحديث عن النبي ﷺ وهو حديث لا بأس به، جيد، نعم. المقدم: لكن بالنسبة للأذان هل يكون بعد الولادة مباشرة أو في اليوم السابع؟ الشيخ: الأمر واسع، إما في اليوم الأول، وإلا في يوم السابع، واسع. المقدم: شكرًا، أثابكم الله.","link":"https://binbaz.org.sa/fatwas/13608/حكم-تحنيك-الطفل-والاذان-في-اذنيه-وحلق-راسه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_664/nour_66410.mp3","categories":["أحكام المولود"]},{"id":15567,"question":"هذا السائل الذي رمز لاسمه بـ (ح. ر. ع) يقول: لي مجموعة من الأبناء والبنات، ولم أعق عنهم عقيقة واحدة عند ولادتهم جهلًا مني، والآن هل يلزمني أن أذبح عن كل واحد منهم، أم أذبح بنية الجميع درءًا للتكلفة المالية؟","title":"ما حكم من لم يعق عن أبنائه عند ولادتهم؟","answer":"الجواب: سنة عن كل واحد، سنة إذا تيسر لك تذبح عن كل واحد، الذكر ثنتان، والأنثى واحدة، إذا تيسر، وإن كان فيه مشقة، فالحمد لله، ليست بواجبة، العقيقة سنة تذبح عن الأنثى شاة واحدة، وعن الذكر اثنتين، وهذا هو المشروع، ولو كانوا كبارًا إذا نسيت أو جهلت أو عجزت وهم صغار، والحمد لله، وإذا شق ذلك سقطت، والحمد لله، نعم.\nالمقدم: متى تذبح العقيقة يا سماحة الشيخ؟ الشيخ: الأفضل يوم السابع، وإن ذبحها بعد ذلك فلا بأس، الأفضل يوم السابع، وإن ذبحها بعد ذلك فلا حرج، في أي وقت، وقالت عائشة -رضي الله عنها-: «في الرابع عشر إذا فات السابع، فإن فات الرابع عشر في الواحد والعشرين» فإذا فعل في الرابع عشر أو في الحادي والعشرين، أو في أي وقت، كفى، والحمد لله. المقدم: هل له أن يجمع الأقرباء والأصدقاء؟ الشيخ: أمرها واسع، إن شاء جمع عليها أقاربه وجيرانه، وإن شاء وزع عليهم، وإن شاء وزع بعضًا، وأكل بعضًا، الأمر فيها واسع. المقدم: ولو أكلها جمعيًا -يا سماحة الشيخ- لأهل بيته ما فيه مانع؟\nالشيخ: ما أعلم مانع، لكنه يتصدق منها أفضل؛ خروجًا من الخلاف، نعم. المقدم: الحكمة من ذبح العقيقة يا سماحة الشيخ؟ الشيخ: الشكر لله، الشكر لله -جل وعلا- على نعمة الولد، نعم، . المقدم: أحسن الله إليكم يا سماحة الشيخ، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/14103/ما-حكم-من-لم-يعق-عن-ابناىه-عند-ولادتهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_570/57005.mp3","categories":["أحكام المولود"]},{"id":15627,"question":"يقول هذا السائل من الأردن -يا سماحة الشيخ-: أنا رجل لم أعق عن أولادي لعدم الإمكانية، والآن والحمد لله تيسر ذلك من مال وغيره؛ فهل يجب علي أن أعق على أولادي جميعًا؟ وإن فعلت ذلك هل تعد عقيقة؟","title":"حكم العقيقة عن الكبير لعدم الاستطاعة في الصغر","answer":"الجواب: السنة العق عنهم ولو كبروا، إذا كنت وقت الصغر لم يكن عندك قدرة، فالسنة أن تعق عنهم ولو بعد كبرهم؛ لأنها سنة ثابتة مستقرة، فإذا عققت عنهم بعد كبرهم لما يسر الله عليك فهذا هو السنة، عن الذكر شاتان، وعن الأنثى واحدة، هذا هو السنة، تذبح وتأكل منها وتطعم وتتصدق، أو تجمع عليها أقاربك أو جيرانك؛ كل ذلك حسن إذا يسر الله أمرك، تعق عنهم ولو بعد كبرهم، نعم. المقدم: جزاكم الله خيرًا. الشيخ: وليست واجبة، ولكنها سنة، نعم.","link":"https://binbaz.org.sa/fatwas/14166/حكم-العقيقة-عن-الكبير-لعدم-الاستطاعة-في-الصغر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_571/57110.mp3","categories":["أحكام المولود"]},{"id":15717,"question":"ما هي الأمور التي يفعلها الإنسان إذا ولد له مولود؟","title":"الأمور التي يفعلها الإنسان إذا ولد له مولود","answer":"الجواب: إذا ولد له مولود يشكر الله ويحمده، ويسأله للمولود الصلاح، وأن ينبته الله نباتًا حسنًا، ويستحب له أن يسمي يوم السابع، ويختار الاسم الطيب الحسن، ويستحب له أيضًا أن يحلق رأسه إن كان ذكر، ويعق عنه ذبيحتين، وإن كان أنثى ذبيحة واحدة، هذا مستحب يوم السابع، وإن سماه في أول يوم فلا بأس. ومما ينبغي للمؤمن عندما يهبه الله الأولاد: أن يهتم بشكر الله، وسؤاله أن الله يصلحهم، وأن الله ينبتهم نباتًا حسنًا؛ لأن الأولاد فتنة، فإذا أنبتهم الله النبات الحسن، وأصلح حالهم، صاروا نعمة، قال تعالى: إِنَّمَا أَمْوَالُكُمْ وَأَوْلادُكُمْ فِتْنَةٌ [التغابن:15] فهي اختبار وامتحان، فإذا أصلح الله الولد صار نعمة عظيمة، سواء كان ذكرًا أو أنثى، نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14278/الامور-التي-يفعلها-الانسان-اذا-ولد-له-مولود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_706/nour_70611.mp3","categories":["أحكام المولود"]},{"id":15722,"question":"ماذا عن العقيقة بالنسبة للبنت سماحة الشيخ؟","title":"ما حكم العقيقة عن البنت؟","answer":"الجواب: العقيقة سنة عن الجميع، فعن المرأة ذبيحة واحدة من الغنم، تجزئ في الضحية: ثني المعز، أو جذع ضأن، أو أعلى سنًا، تذبح، تقسم على الفقراء والجيران، أو يقسم بعضها، ويأكل بعضها، أو يطبخها ويدعو إليها من أحب من جيرانه وأقاربه، ليس فيها حد محدود، والحمد لله؛ لأن الرسول ﷺ لم يحدد في هذا شيئًا، وعن الذكر ثنتين، الأنثى واحدة، والذكر ثنتين بصفة الضحية، تجزئ في الضحية: إما جذع ضأن، أو ثني معز، هذا هو السنة في العقيقة، أن تكون من الغنم، عن الذكر اثنتان، وعن الأنثى واحدة، يأكل منها، ويطعم، ويتصدق، نعم. المقدم: جزاكم الله خيرًا، ماذا لو جمع أصدقاءه في البيت مثلًا وأطعمهم ؟\nالشيخ: كله طيب، إذا جمعهم طيب، وإذا وزع عليهم طيب، وإذا وزع بعضًا، وترك بعضًا طيب، الحمد لله، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14284/ما-حكم-العقيقة-عن-البنت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_706/nour_70612.mp3","categories":["أحكام المولود"]},{"id":15729,"question":"أيضًا أخونا محمد حسين مسلم المالكي من جدة، يسأل سماحتكم تكملة لبحث العقيقة، فيقول: إذا لم يستطع الإنسان أن يعق عن أولاده أو بناته عند ولادتهم، فهل يقضيها، ولو كبروا عندما رزقه الله ووسع عليه؟","title":"إذا لم يستطع أن يعق عن أولاده وهم صغار فهل يقضيها؟","answer":"الجواب: نعم يقضيها ولو كبروا، إذا تيسرت يذبحها عن الذكور والإناث، والحمد لله، نعم. المقدم: والحال بالنسبة لأكلها أو تقسيمها.\nالشيخ: مثل لو كان في حال الصغر، مثل لو ذبحها في حال الصغر، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14294/اذا-لم-يستطع-ان-يعق-عن-اولاده-وهم-صغار-فهل-يقضيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_706/nour_70615.mp3","categories":["أحكام المولود"]},{"id":15878,"question":"السقط هل له عقيقة؟","title":"حكم العقيقة عن السقط","answer":"الجواب: نعم، إذا سقط من الشهر الخامس، أو ما بعده: يسمى، ويغسل، ويصلى عليه، ويعق عنه، نعم.\nالمقدم: إذا مات بعد الولادة بيومين، أو مضى عليه شهر أو أكثر. الشيخ: إذا ولد سقطًا في الخامس أو السادس أو السابع، أو مات بعد الوضع بيوم أو يومين كله واحد: يسمى، ويغسل، ويصلى عليه، ويعق عنه، نعم. المقدم: وما حكم تأخير العقيقة عن اليوم السابع؟ الشيخ: لا حرج في ذلك، لكن السنة يوم السابع، السنة يوم السابع، وإذا لم يعق إلا بعد ذلك فلا حرج في ذلك.","link":"https://binbaz.org.sa/fatwas/14467/حكم-العقيقة-عن-السقط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_577/57704.mp3","categories":["أحكام المولود"]},{"id":16005,"question":"من رفحة رسالة بعث بها المستمع عبد الرحمن نور محمد هيئة الإغاثة الإسلامية العالمية، أخونا له جمع من الأسئلة في أحدها يقول: بالنسبة للعقيقة أيهما أفضل أن تكون وليمة أم توزع؟جزاكم الله خيرًا.","title":"كيفية التصرف في لحم العقيقة","answer":"الجواب: الأمر فيها واسع، العقيقة الأمر فيها واسع لم يرد فيها عن النبي ﷺ ما يدل على هذا أو هذا، بل تذبحها، فإن شئت وزعتها على جيرانك وأقاربك والفقراء، وإن شئت وزعت بعضها، وجمعت من ترى من إخوانك وجيرانك على الباقي، وإن شئت جمعتهم على جميعها كله خير، كله طيب تأكل وتطعم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14633/كيفية-التصرف-في-لحم-العقيقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_747/nour_74714.mp3","categories":["أحكام المولود"]},{"id":16006,"question":"سمعت أن عظام العقيقة لا تكسر، بل تفكك ما علة ذلك؟ وهل إذا كسر العظم عند الوليمة يُؤثر ذلك على المعق عنه؟جزاكم الله خيرًا.","title":"استحباب عدم تكسير عظام العقيقة","answer":"الجواب: هذا ورد عن عائشة -رضي الله عنها-: \"أن العقيقة تنزع جدولًا، وأعضاؤها لا تكسر\" تفاؤل، من باب التفاؤل في سلامة الولد، وعدم تعرضه للسوء، وليس هذا بواجب، بل هو مستحب، وإن كسرها فلا حرج، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14635/استحباب-عدم-تكسير-عظام-العقيقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_747/nour_74715.mp3","categories":["أحكام المولود"]},{"id":16011,"question":"يقول: بعض الناس يعملون وليمة الزواج مع وليمة العقيقة، فهل يجوز ذلك أم لكل طريقه؟وجهونا، جزاكم الله خيرًا.","title":"حكم جمع وليمة الزواج والعقيقة","answer":"الجواب: لا حرج في ذلك، لا حرج إذا جمع الوليمتين فلا بأس، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14637/حكم-جمع-وليمة-الزواج-والعقيقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_747/nour_74716.mp3","categories":["أحكام المولود"]},{"id":16215,"question":"تسأل وتقول: هل من السنة حلق شعر البنت الوليدة؟","title":"حكم حلق شعر المولودة","answer":"الجواب: الحلق يكون لشعر الولد، أما البنت فلا يشرع حلق شعرها يقول النبي ﷺ: كل غلام مرتهن بعقيقته، تذبح عنه يوم سابعه، ويحلق ويسمى فهذا في حق الغلام: الحلق، أما البنت فيربى رأسها، ويعتنى به، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14888/حكم-حلق-شعر-المولودة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_751/nour_75108.mp3","categories":["أحكام المولود"]},{"id":17149,"question":"يقول: عندنا عادات متبعة في المواليد عندما تضع المرأة جنينًا لا يسمونه إلا بعد أسبوع، وسؤالي: هل إذا أراد الله  وتوفي قبل أن يسمى هل يسمى بعد وفاته، أم ما هو توجيه الناس؟ جزاكم الله خيرًا.","title":"حكم تسمية المولود بعد وفاته","answer":"الجواب: المولود يسمى يوم ولادته، ويوم السابع، كله سنة، الرسول ﷺ سمى بعض أولاد الصحابة، وسمى ابنه إبراهيم يوم ولادته، وإن سماه يوم السابع فهو سنة أيضًا، يقول النبي ﷺ في الحديث الصحيح: كل غلام مرتهن بعقيقته تذبح عنه يوم سابعه، ويحلق ويسمى فهو السنة أن يسمى يوم السابع، ويحلق شعره، وتذبح عنه العقيقة، فإن سمي في اليوم الأول فهو سنة أيضًا، هذا وهذا؛ لأن الرسول ﷺ فعل هذا وهذا، سمى يوم الأول، وأرشد إلى التسمية يوم السابع، فكلها سنة والحمد لله. نعم.  المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15969/حكم-تسمية-المولود-بعد-وفاته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_722/nour_72212.mp3","categories":["أحكام المولود"]},{"id":17150,"question":"السائل يقول في هذا  السائلة أم هادي تقول: عندنا اعتقاد يا سماحة الشيخ بأنه إذا لم يكحل المولود قبل بلوغه أربعين يومًا يصبح غباشًا في عينيه، أي أنه لا يرى جيدًا، هل هذا صحيح؟","title":"هل عدم تكحيل المولود يؤثر على عينيه؟","answer":"الجواب: لا أعرف له أصلًا، هذا كلامٌ لا أعرف له أصلًا. نعم، لا أصل له. نعم.","link":"https://binbaz.org.sa/fatwas/15968/هل-عدم-تكحيل-المولود-يوثر-على-عينيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_589/58929.mp3","categories":["أحكام المولود"]},{"id":17183,"question":"تقول السائلة يا شيخ: هل العقيقة سنة، أم واجبة؟ وهل الأفضل توزيعها على الأقارب، والجيران، والفقراء، أم الأفضل أن ندعو الأصدقاء في البيت؟ وهل الأفضل أن نقوم بتقسيمها أثلاث كما في الأضحية؟","title":"حكم العقيقة وكيفية توزيعها","answer":"الجواب: العقيقة سنة عن الذكر ثنتان، وعن الجارية واحدة، هذا هو السنة، تذبح يوم السابع، وليس في توزيعها نص واضح، فإذا وزع منها على الجيران، أو الأقارب، وأكل بعضها، أو دعا الجيران عليها، أو بعض الجيران، وأعطى بعض الفقراء، كله واسع، والأمر واسع، وبعض أهل العلم جعلها كالأضحية، يأكل ثلثًا، ويتصدق بثلث، ويهدي ثلثًا، لكن ليس عليه دليل، فالأولى في هذا أنه يأكل منها، أو يتصدق، أو يهدي، وليس في هذا حدٌ محدود، والحمد لله. نعم.  المقدم: الحمد لله.","link":"https://binbaz.org.sa/fatwas/16001/حكم-العقيقة-وكيفية-توزيعها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_590/59011.mp3","categories":["أحكام المولود"]},{"id":17184,"question":"تقول السائلة: متى يبدأ حساب اليوم السابع؟ بمعنى: هل يحسب اليوم إذا كانت الولادة قبل الفجر، أو بعد الفجر؟ وكذلك بالنسبة لعدة الوفاة، وعدة المطلقة؟","title":"متى يبدأ حساب اليوم الأول للمولود؟","answer":"الجواب: يحسب اليوم الذي وقع فيه الولادة، إذا ولد في صباح يوم الإثنين، أو العصر، أو الظهر يحسب هذا أول يوم، وإذا وقع في الليل، ليلة الإثنين يحسب يومها؛ يوم الإثنين الذي ولد في ليلته، فإذا جاء السابع؛ سمي فيه، وذبحت العقيقة. المقصود: أنه يحسب اليوم الأول الذي ولد فيه، ولو كان في العصر يحسب، هذا أول يوم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16002/متى-يبدا-حساب-اليوم-الاول-للمولود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_590/59012.mp3","categories":["أحكام المولود"]},{"id":17260,"question":"من أسئلة هذا السائل أبو أحمد يقول سماحة الشيخ: هل يجوز أن أذبح شاة واحدة، أو جديًا واحدًا في حالة المولود ولدًا؟ وهل يكفي ذلك؟ وهل يجوز أن نشترك سبعة في بقرة في عقيقة واحدة، حيث أن والدي لم يفعل لنا عقيقة؟","title":"حكم العقيقة بسبع من البقر أو الإبل","answer":"الجواب: السنة في العقيقة ذبيحتان عن الذكر، وذبيحة واحدة عن الأنثى، هكذا «أمر النبي ﷺ أن يعق عن الغلام شاتان، وأن يعق عن الجارية شاة، والمراد بذلك شاتان تجزئان في الأضحية، يعني: ثني معز، أو جذع ضأن، هذا هو السنة، الغنم عن الذكر ثنتان، وعن الأنثى واحدة، أما إذا عق بسبعين من البدنة والبقرة، نرجو أن يجزئ، فنرجو أن يجزئ، لكن الأفضل الغنم. المقدم: أحسن الله إليكم، وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16096/حكم-العقيقة-بسبع-من-البقر-او-الابل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_592/59211.mp3","categories":["أحكام المولود"]},{"id":17615,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع محمد ... بن إبراهيم باري من غينيا كناتري له جمع من الأسئلة في أحدها يسأل ويقول: ما حكم العقيقة؟","title":"ما حكم العقيقة؟","answer":"الجواب: بسم الله الرحمن الرحيم. الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد:\nفالعقيقة هي الذبيحة التي تذبح عن المولود في اليوم السابع من ولادته، يقال لها: عقيقة ويقال لها: نسيكة ويسميها بعض الناس: تميمة، وهي عن الذكر ثنتان وعن الأنثى واحدة من الغنم، تجزئ في الأضحية يعني: جذع ضأن أو ثني المعز فما فوق، فهذه يقال لها: العقيقة، وهي سنة مؤكدة؛ لأن الرسول أمر بها عليه الصلاة والسلام، أمر أن يعق عن الغلام شاتان وعن الجارية شاة، وقال: كل غلام مرتهن بعقيقته تذبح عنه يوم سابعه ويحلق ويسمى.\nفالسنة لأب الطفل أن يذبح عن ولده الصغير ثنتين إذا كان ذكرًا وعن الجارية واحدة في اليوم السابع، فإن لم يتيسر ذبحها بعد ذلك، في الرابع عشر في الحادي والعشرين كما يروى عن عائشة رضي الله عنها أو في غير ذلك، ليس لها حد محدود بعد السبع، إن تيسر اليوم السابع فهو أفضل ويحلق رأس الطفل الذكر ويسمى وإن سمي عند ولادته فلا بأس، قد سمى النبي ﷺ بعض أولاد الأنصار يوم الولادة وسمى ابنه إبراهيم يوم الولادة وإن سمي يوم السابع فكذلك كله سنة.\nأما العقيقة والحلق يكون يوم السابع، حلق رأس الذكر أما الأنثى لا، وإذا ذبحها بعد ذلك بشهر أو شهرين أو سنة أو أكثر كل هذا لا بأس به، والسنة أن يأكل منها ويطعم ويتصدق منها وإن جمع عليها جيرانه وأقاربه أو تصدق بها كلها فلا بأس كله طيب، ليس فيها حد محدود بحمد الله، الرسول ﷺ أمر بها ولم يقل: افعلوا بها كذا وكذا، فدل على التوسعة إن أكل منها أو ادخر منها أو أطعم جيرانه، أو تصدق بها كلها لكن الأفضل أن يتصدق منها بعض الشيء، وإن وزعها كلها أو جمع الجيران والأقارب عليها والأصدقاء كله طيب. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16538/ما-حكم-العقيقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_842/nour_84201.mp3","categories":["أحكام المولود"]},{"id":17876,"question":"ما حكم حلق شعر المولود؟","title":"حكم حلق شعر المولود","answer":"الجواب: السنة أن يحلق يوم السابع، إذا كان ذكرًا، قال النبي ﷺ: كل غلام مرتهنٌ بعقيقته، تذبح عنه يوم السابع، ويحلق، ويسمى، فالسنة أن يحلق يوم السابع، وأن يسمى يوم السابع، وأن يعق عنه، إذا كان ذكرًا بشاتين، وإذا كانت أنثى بواحدة، أما الحلق فيختص بالذكر.\nالمقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/16881/حكم-حلق-شعر-المولود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_728/nour_72810.mp3","categories":["أحكام المولود"]},{"id":18559,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المنطقة الشرقية، الدمام، وباعثتها إحدى الأخوات من هناك تقول: (ع. ح. ق) أختنا تسأل عن الوقت المناسب لتسمية المولود، ومن هو الأحق بتسميته؟","title":"الوقت المناسب لتسمية المولود والأحق بتسميته","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فالأحق بالتسمية هو الأب -هو والد الطفل- إذا كان موجودًا، وإذا كان غير موجود فالأكبر من أولياء الطفل، ويستحب التعاون في ذلك والتشاور بين الوالد والوالدة، حتى يختار الجميع الاسم الحسن، وأفضل الأسماء ما عبد لله  في حق الرجال: كعبدالله وعبدالرحمن وعبدالملك وعبدالكريم، ونحو ذلك. وفي حق النساء ما كان متعارفًا بين نساء الصحابة، ومن بعدهم من المؤمنات الأسماء المعروفة التي ليس فيها بشاعة، ولا ما يدل على اختيار كأسماء الجاهلية من أسماء الكفرة والكافرات، يختار المؤمن الأسماء المعروفة بين المسلمين، هذا هو الأفضل. أما ما عُبِّد لغير الله، فلا يجوز كعبدالحسين أو عبدالنبي أو عبدالكعبة هذا لا يجوز. والأفضل أن تكون التسمية يوم السابع للرجل والمرأة جميعًا؛ لقول النبي ﷺ: كل غلام مرتهن بعقيقته تذبح عنه يوم سابعه، ويحلق ويسمى رواه الإمام أحمد وأهل السنن بإسناد صحيح. فالأفضل التسمية يوم السابع، وإن سمي يوم الولادة فلا بأس، وقد سمى النبي ﷺ ولده إبراهيم يوم ولادته، وسمى أولاد بعض الصحابة في اليوم الأول فلا بأس، سنة أيضًا، وفي يوم السابع سنة، هذا هو الأفضل في الزمان. وفي الاسم يختار الأسماء الطيبة الحسنة التي قد اعتادها المسلمون من عهد الصحابة إلى يومنا هذا، وفي أسماء الرجال الأفضل فيها ما كان معبدًا لله؛ لقوله ﷺ: أحب الأسماء إلى الله عبدالله وعبدالرحمن ما عبد لله كان أفضل، وهكذا الأسماء المعتادة مثل: محمد وصالح وسعد وسعيد، وأشباه ذلك، كلها أسماء صالحة، لكن أفضلها ما عبد لله -سبحانه وتعالى- وأفضل الأيام يوم السابع، وهكذا اليوم الأول، نعم. المقدم: جزاكم الله خيرًا، ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/17669/الوقت-المناسب-لتسمية-المولود-والاحق-بتسميته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_917/nour_91701.mp3","categories":["أحكام المولود"]}]
